// ============================================================
// BOOTSTRAP CONFIG
// 2026-08-28: SHEET_ID sebelumnya masih menunjuk spreadsheet Persada
// (1dJWq7iq...) -- sisa fork yang tidak pernah dibaca node mana pun,
// tapi menyesatkan saat debug. Sekarang diselaraskan ke spreadsheet
// "VIRA Steven Database" yang benar-benar dipakai node Google Sheets.
// ============================================================
const SHEET_ID = '1C5gF1TTJFAHCrfVESiaIhAts6iByRH9BRjLqBCO_Yxk';   // VIRA Steven Database
const wh = $input.first() ? $input.first().json : {};
return [{ json: { ...wh, sheet_id: SHEET_ID } }];

// ============================================================
// PARSE CONFIG (ENGINE) — baca tab CONFIG (key|value) jadi objek config.
// Nilai list/JSON ditulis sbg JSON string di sel value.
// Perubahan 2026-07-17: default bot_name 'VIRA' -> 'Vira'.
// ============================================================
const rows = $('Read CONFIG').all().map(i => i.json);
const sheetId = $('Bootstrap Config').first().json.sheet_id || '';
const raw = {};
for (const r of rows) {
  const k = String(r.key ?? r.Key ?? r.KEY ?? '').trim();
  if (!k) continue;
  raw[k] = (r.value ?? r.Value ?? r.VALUE ?? '');
}
const str = (k, def='') => { const v = raw[k]; return (v===undefined||v===null||String(v).trim()==='') ? def : String(v).trim(); };
const num = (k, def) => { const s = str(k,''); if (s==='') return def; const n = Number(s); return Number.isFinite(n)?n:def; };
const bool = (k, def=false) => { const v = str(k,'').toLowerCase(); if (v==='') return def; return ['true','yes','y','on','1','aktif','ya'].includes(v); };
const jsonArr = (k) => { try { const v = str(k,''); if (!v) return []; const p = JSON.parse(v); return Array.isArray(p) ? p : []; } catch(e){ return []; } };

const config = {
  sheet_id: sheetId,
  client_name: str('client_name', 'Persada Cisoka Residence'),
  bot_name: str('bot_name', 'Vira'),
  bot_language: str('bot_language', 'id'),
  system_prompt: str('system_prompt', ''),
  admin_phone: str('admin_phone', ''),
  admin_phone_display: str('admin_phone_display', ''),
  field_team_phone: (() => {
    const a = jsonArr('field_team_phone');
    if (a.length) return a.map(x => String(x).replace(/\D/g,'')).filter(Boolean);
    const s = str('field_team_phone','');
    return s ? [s.replace(/\D/g,'')].filter(Boolean) : [];
  })(),
  media_team_phone: (() => {
    const a = jsonArr('media_team_phone');
    if (a.length) return a.map(x => String(x).replace(/\D/g,'')).filter(Boolean);
    const s = str('media_team_phone','');
    return s ? [s.replace(/\D/g,'')].filter(Boolean) : [];
  })(),
  brochure_url: str('brochure_url', ''),
  media_catalog: jsonArr('media_catalog'),
  survey_slots: jsonArr('survey_slots'),
  survey_open_hour: num('survey_open_hour', 8),
  survey_close_hour: num('survey_close_hour', 17),
  followup_max: num('followup_max', 3),
  followup_interval_hours: num('followup_interval_hours', 24),
  followup_open_hour: num('followup_open_hour', 9),
  followup_close_hour: num('followup_close_hour', 18),
  followup_templates: jsonArr('followup_templates'),
  lead_source_map: jsonArr('lead_source_map'),
  whitelist_enabled: bool('whitelist_enabled', false),
  // Dibaca Blocklist Gate. Sebelum 2026-09-05 tiga kunci ini tidak pernah
  // dirakit di sini, jadi blocklist & proteksi anti-loop selalu kosong.
  blocklist_numbers: jsonArr('blocklist_numbers').map(x => String(x).replace(/\D/g,'')).filter(Boolean),
  bot_wa_number: str('bot_wa_number', '').replace(/\D/g, ''),
  ignore_self_number: bool('ignore_self_number', true),
  whitelist_numbers: jsonArr('whitelist_numbers').map(x => String(x).replace(/\D/g,'')),
  rate_limit_max: num('rate_limit_max', 5),
  rate_limit_window_sec: num('rate_limit_window_sec', 60),
  debounce_seconds: num('debounce_seconds', 60),
  // Kredensial Kirimi utk endpoint multipart send-message-file (upload binary).
  // Custom-auth n8n TIDAK reliabel meng-inject body ke multipart/form-data,
  // jadi user_code/secret/device_id di-supply sbg field form via CONFIG sheet.
  // Node teks (JSON body) tetap pakai credential httpCustomAuth.
  // ---- [V2.1 VISION] toggle add-on & batas biaya (semua opsional di sheet CONFIG) ----
  // vision_mode:
  //   'off'  = perilaku V1.3 - media tanpa teks di-drop, Vira diam.
  //   'ack'  = media DIAKUI sopan tapi TIDAK dikirim ke Claude. NOL biaya.
  //            <- pakai ini selama add-on vision belum disetujui klien.
  //   'full' = vision aktif penuh (add-on berbayar, ~Rp 40 / chat bergambar).
  // Kalau key 'vision_mode' tidak ada di sheet, jatuh ke key lama 'vision_enabled'
  // supaya sheet yang belum diupdate tetap jalan.
  vision_mode: (() => {
    const m = str('vision_mode', '').toLowerCase();
    if (['off', 'ack', 'full'].includes(m)) return m;
    return bool('vision_enabled', true) ? 'full' : 'ack';
  })(),
  vision_enabled: bool('vision_enabled', true),
  vision_max_images: num('vision_max_images', 3),
  // Default harus sama dengan fallback di `Siapkan Vision Request`. Sebelumnya
  // 'claude-haiku-4-5' dikirim ke api.deepseek.com dan selalu ditolak 400,
  // jadi setiap gambar berakhir di cabang 'sistem gagal membaca'.
  vision_model: str('vision_model', 'deepseek-v4-flash-vision-exp'),
  vision_max_tokens: num('vision_max_tokens', 1000),
  kirimi_user_code: str('kirimi_user_code', ''),
  kirimi_secret: str('kirimi_secret', ''),
  kirimi_device_id: str('kirimi_device_id', ''),
};
const passthrough = $('Bootstrap Config').first() ? $('Bootstrap Config').first().json : {};

// ── Gerbang kewarasan CONFIG (2026-09-06) ──
// `Read CONFIG` bersetel alwaysOutputData:true, jadi pembacaan tab CONFIG yang
// gagal atau kosong TIDAK memerahkan node itu — dia mengeluarkan satu item kosong,
// `raw` jadi {}, dan seluruh config diam-diam jatuh ke nilai default. Akibatnya
// error baru meledak enam node kemudian, di `Send WA + Verify (Kirimi)`, dengan
// pesan yang menuduh kredensial padahal yang salah adalah pembacaan sheet.
// Kejadian 2026-09-06: satu sel kunci di tab CONFIG tertimpa huruf 'f', jadi baris
// kirimi_user_code hilang; nilainya masih ada, namanya yang lenyap.
// Diperiksa di sini, di tempat kuncinya dirakit, supaya pesannya menunjuk penyebab.
if (rows.length === 0 || Object.keys(raw).length === 0) {
  throw new Error('Tab CONFIG terbaca kosong (' + rows.length + ' baris). '
    + 'Cek: (a) kolom judul baris 1 harus persis "key" dan "value", '
    + '(b) service account masih punya akses ke spreadsheet ' + (sheetId || '(sheet_id kosong)') + ', '
    + '(c) nama tab masih "CONFIG". Semua nilai config jatuh ke default kalau ini dibiarkan.');
}

// Kredensial Kirimi: tanpa ketiganya, TIDAK ADA pesan yang bisa keluar sama sekali —
// balasan ke prospek, notif brief deck, notif handover, notif UNKNOWN, semuanya.
// Jadi berhenti di sini dengan menyebut kunci mana yang harus diisi.
const WAJIB = ['kirimi_user_code', 'kirimi_secret', 'kirimi_device_id'];
const hilang = WAJIB.filter(k => !String(config[k] || '').trim());
if (hilang.length) {
  const adaBarisnya = WAJIB.filter(k => Object.prototype.hasOwnProperty.call(raw, k));
  throw new Error('Kunci wajib kosong di tab CONFIG: ' + hilang.join(', ') + '. '
    + 'Yang barisnya ketemu: ' + (adaBarisnya.join(', ') || '(tidak satu pun)') + '. '
    + 'Kalau nilainya terlihat ada di sheet tapi tetap dilaporkan kosong, '
    + 'yang salah nama kuncinya di kolom "key", bukan nilainya.');
}

return [{ json: { ...passthrough, config } }];

// Blocklist Gate - VIRA Steven (v3, 2026-09-05)
// Bot ini PUBLIK: defaultnya semua orang boleh masuk.
//
// Perbaikan 2026-09-05:
// (1) Node ini menerima item dari Parse Config, yang isinya hasil spread payload
//     webhook - nomor pengirim ada di `body.from`, BUKAN di `from` tingkat atas.
//     Versi lama membaca item.from (selalu undefined), jadi blocklist dan proteksi
//     anti-loop TIDAK PERNAH aktif satu kali pun.
// (2) Gerbang uji coba pindah ke sini dari node `IF (Whitelist)` yang mengunci bot
//     ke dua nomor. Sekarang dikendalikan CONFIG, bukan ditanam di kabel:
//       whitelist_enabled = false (default) -> semua orang masuk  = MODE IKLAN
//       whitelist_enabled = true            -> hanya whitelist_numbers = MODE UJI
const cfg  = $('Parse Config').first().json.config || {};
const item = $input.first().json || {};
const body = item.body || {};

const digits = (s) => String(s || '').replace(/\D/g, '');
const from = digits(body.from ?? item.from ?? item.no_wa ?? '');
const lid  = digits(body.originLid ?? item.originLid ?? item.lid ?? '');
const cocok = (daftar) => daftar.length > 0
  && ((from && daftar.includes(from)) || (lid && daftar.includes(lid)));

// 1) jangan pernah membalas diri sendiri (bisa memicu loop tak berujung)
const botNumber = digits(cfg.bot_wa_number || '');
if (cfg.ignore_self_number !== false && botNumber && (from === botNumber || lid === botNumber)) {
  console.log('STOP: pesan dari nomor bot sendiri.');
  return [];
}

// 2) blocklist manual dari CONFIG
if (cocok((cfg.blocklist_numbers || []).map(digits).filter(Boolean))) {
  console.log('STOP: nomor ada di blocklist. from=' + from + ' lid=' + lid);
  return [];
}

// 3) whitelist OPSIONAL - hanya aktif kalau CONFIG.whitelist_enabled = true.
//    Whitelist yang aktif tapi kosong TIDAK mematikan bot: itu kegagalan yang
//    paling mahal (semua prospek diam-diam dibuang), jadi sengaja diabaikan.
if (cfg.whitelist_enabled === true) {
  const putih = (cfg.whitelist_numbers || []).map(digits).filter(Boolean);
  if (!putih.length) {
    console.warn('whitelist_enabled=true tapi whitelist_numbers kosong - gerbang diabaikan.');
  } else if (!cocok(putih)) {
    console.log('STOP: whitelist aktif, nomor tidak terdaftar. from=' + from + ' lid=' + lid);
    return [];
  }
}

return $input.all();

// NODE: Chat Counter
// ====================================================================
// [V2 - VISION] Gerbang masuk & parsing payload Kirimi.
// V1.3: SEMUA messageType != "text" di-DROP di sini (return []).
// V2  : - gambar (dengan / tanpa caption) DITERUSKAN, media_url dibawa
//         ke MSG_BUFFER supaya ikut logika debounce & gabung pesan.
//       - media non-gambar (video/suara/dokumen/lokasi) diteruskan
//         sebagai PENANDA saja (tidak dikirim ke Vision) supaya Vira
//         bisa menjawab sopan, bukan diam.
// ====================================================================
const webhookData = $input.first();
const body = webhookData.json.body || {};

// Ambil data dari Kirimi
const userMessage = body.message || "";
const messageType = String(body.messageType || "").trim().toLowerCase();
const userNumber = body.from || "unknown";  // TIDAK strip @lid, passthrough as-is
const _isLid    = String(userNumber).toLowerCase().includes('@lid');
const userLid   = String(body.originLid || (_isLid ? userNumber : '')).replace(/\D/g, '');
const userPhone = _isLid ? '' : String(userNumber).replace(/\D/g, '');
const userName = body.name || body.pushName || body.notifyName || "User";
const isFromMe = body.isFromMe === true;
const eventType = body.event || "";

// -- [V2] Deteksi media masuk ------------------------------------------------
// Nama field URL bisa beda antar versi gateway -> cek beberapa kandidat.
const mediaUrl = String(
  body.mediaUrl ?? body.media_url ?? body.fileUrl ?? body.file_url ?? body.url ?? ''
).trim();
const mediaMime = String(
  body.mimetype ?? body.mimeType ?? body.mime_type ?? ''
).trim().toLowerCase();

const IMAGE_TYPES = ['image','imagemessage','photo','gambar'];
// [V2.1] Stiker dipindah ke media non-gambar: TIDAK dikirim ke Vision (nol biaya).
// Di chat WA Indonesia stiker dipakai sbg basa-basi, frekuensinya bisa > foto asli.
const OTHER_MEDIA_TYPES = ['video','videomessage','audio','audiomessage','ptt','voice',
  'document','documentmessage','file','location','locationmessage','contact','vcard',
  'sticker','stickermessage'];
// [V2.1] Tipe sistem: TIDAK PERNAH memicu balasan, walaupun membawa teks.
// V2.0 memakai blacklist implisit (lolos asal body.message tidak kosong), sehingga
// reaction beremoji ikut diproses jadi 1 eksekusi penuh + Vira membalasnya.
const DROP_TYPES = ['reaction','reactionmessage','protocol','protocolmessage',
  'status','statusmessage','revoked','revoke','poll_update','pollupdate',
  'e2e_notification','notification','call','call_log','ciphertext'];

const looksImage      = IMAGE_TYPES.includes(messageType) || mediaMime.startsWith('image/');
const looksOtherMedia = OTHER_MEDIA_TYPES.includes(messageType);
const hasText         = !!userMessage && String(userMessage).trim() !== '';

// media_kind: 'none' | 'image' (bisa dibaca Vision) | 'other' (cuma penanda)
let mediaKind = 'none';
if (looksImage && mediaUrl) mediaKind = 'image';
else if (looksImage || looksOtherMedia) mediaKind = 'other';
else if (mediaUrl && messageType !== 'text' && messageType !== 'chat') mediaKind = 'other';

const MEDIA_LABEL = {
  video:'video', videomessage:'video',
  audio:'pesan suara', audiomessage:'pesan suara', ptt:'pesan suara', voice:'pesan suara',
  document:'dokumen', documentmessage:'dokumen', file:'dokumen',
  location:'lokasi', locationmessage:'lokasi', contact:'kontak', vcard:'kontak',
  sticker:'stiker', stickermessage:'stiker'
};
const mediaLabel = mediaKind === 'image'
  ? 'gambar'
  : (mediaKind === 'other' ? (MEDIA_LABEL[messageType] || 'lampiran') : '');

// [V3.2] Gerbang 0 - tanpa pengenal pengirim, ini bukan pesan orang.
// Webhook ini juga menerima event perangkat dari Kirimi, dan sebagiannya membawa
// field `message` berisi teks sehingga lolos gerbang "bukan teks valid" di bawah.
// Contoh nyata (2026-09-06 11:25 WIB):
//   { event:'device.last_active', deviceId:'D-BTUYM', message:'Device last active updated' }
// Syaratnya PENGENAL, bukan daftar nama event: pesan dari manusia selalu membawa
// salah satu field di bawah, event perangkat tidak pernah. Daftar nama event akan
// basi begitu Kirimi menambah jenis baru; syarat ini tidak.
const _idKandidat = [body.from, body.senderAlt, body.sender, body.remoteJid,
                     body.chatId, body.participant, body.author, body.originLid];
const _adaPengenal = _idKandidat.some(v => String(v ?? '').replace(/\D/g, '') !== '');
if (!_adaPengenal) {
    // warn, bukan throw: execution tetap hijau, tapi bentuk payloadnya terekam.
    // Kalau suatu saat nomor prospek datang di field yang belum kita baca, jejaknya
    // ketahuan di sini sebelum ada chat yang diam-diam tidak terbalas.
    console.warn('STOP: payload tanpa pengenal pengirim - bukan pesan chat. event='
        + String(body.event || '(tidak ada)')
        + ' | field=' + Object.keys(body).join(','));
    return [];
}

// [V2.1] Gerbang 1 - tipe sistem/reaction selalu dibuang, walau membawa teks.
if (DROP_TYPES.includes(messageType)) {
    console.log('STOP: tipe sistem/reaction, tidak diproses. type=' + messageType);
    return [];
}

// [V2.1] Gerbang 2 - mode add-on. vision_mode=off => perilaku V1.3 (media di-drop).
// Chat Counter berada SESUDAH Parse Config di rantai (Parse Config -> Whitelist Gate
// -> Chat Counter), jadi referensi ini valid.
const cfgCC = (() => { try { return $('Parse Config').first().json.config || {}; } catch (e) { return {}; } })();
const visionModeCC = String(cfgCC.vision_mode || 'full').toLowerCase();
// Setara V1.3 PERSIS: V1.3 membuang semua messageType != 'text', termasuk gambar
// yang ADA captionnya. Jadi di mode 'off' media di-drop tanpa melihat ada teks/tidak.
if (visionModeCC === 'off' && mediaKind !== 'none') {
    console.log('STOP: vision_mode=off, semua media di-drop (perilaku V1.3). type=' + messageType);
    return [];
}

// Filter: buang yang BUKAN teks DAN BUKAN media (status, event sistem)
if (mediaKind === 'none' && !hasText) {
    console.log('STOP: bukan pesan teks valid & tidak ada media. type=' + messageType);
    return [];
}

console.log('LANJUT: type=' + (messageType || '(kosong)') + ' | media=' + mediaKind + ' | text=' + hasText);
console.log('No WA:', userNumber);

// Counter sederhana. $vars adalah fitur berbayar n8n dan read-only di sebagian
// instance; kalau tidak ada, akses langsung melempar TypeError dan SELURUH alur
// mati di node paling awal. Angkanya cuma dipakai untuk log, jadi tidak layak
// jadi titik gagal tunggal.
let counter = 0;
try { counter = Number($vars && $vars.chatCounter) || 0; } catch (e) { counter = 0; }
counter++;
try { if (typeof $vars !== 'undefined' && $vars) $vars.chatCounter = counter; } catch (e) {}

// Format tanggal & jam WIB
const now = new Date();
const formattedDate = now.toLocaleDateString('en-GB', {
    timeZone: 'Asia/Jakarta',
    day: '2-digit',
    month: '2-digit',
    year: 'numeric'
});
const formattedTime = now.toLocaleTimeString('id-ID', {
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hour12: false,
    timeZone: 'Asia/Jakarta'
}).replace(/\./g, ':');

const processStartTs = Date.now();

// [V2] Label utk kolom STATS ("Pesan Pertama"). JANGAN dipakai sebagai
// user_message/prompt -- kata "gambar"/"foto" akan memicu regex wantsMedia
// di Preprocess dan bikin Vira salah kirim brosur.
const statsMessage = hasText ? userMessage : (mediaKind !== 'none' ? ('[' + mediaLabel + ']') : '');

const aiInputText = `[SYSTEM_DATA]
CHAT_COUNTER: ${counter}
USER_NAME: ${userName}
USER_MESSAGE: "${userMessage}"

[USER QUERY]
${userMessage}`;

return [{
    json: {
        chat_counter: counter,
        user_wa: userNumber,
        user_lid: userLid,
        user_phone: userPhone,
        user_name: userName,
        formatted_date: formattedDate,
        formatted_time: formattedTime,
        ai_input_text: aiInputText,
        original_message: userMessage,
        body: body,
        message_type: messageType,
        process_start_ts: processStartTs,
        // ---- [V2 VISION] ----
        media_url: mediaUrl,
        media_kind: mediaKind,
        media_mime: mediaMime,
        media_label: mediaLabel,
        has_media: mediaKind !== 'none',
        stats_message: statsMessage
    }
}];

// ====================================================================
// RESOLVE USER ROW (fondasi identitas)
// No WA = kunci PRIMER, lid = backup. TIDAK PERNAH fallback rows[0].
// ====================================================================
const cc = $('Chat Counter').first().json;
const digits = v => String(v ?? '').replace(/\D/g, '');
const phone = digits(cc.user_phone);
const lid = digits(cc.user_lid);

// ── Dua keadaan yang dulu digabung (2026-09-06) ──
// `Read User STATS` bersetel alwaysOutputData:true. Jadi ketika `Chat Counter`
// sengaja mengembalikan [] untuk reaction / status / protocol / call, node Sheets
// di antaranya TETAP mengeluarkan satu item kosong dan alur sampai ke sini dengan
// cc = {}. Itu bukan payload rusak, itu pesan yang memang sudah dibuang di hulu —
// jadi jangan diperlakukan sebagai error. Kalau tidak dibedakan, setiap emoji
// reaction menghasilkan execution merah plus satu notifikasi error palsu.
const ccKosong = !cc || Object.keys(cc).length === 0;
if (!phone && !lid) {
  if (ccKosong) {
    console.log('Chat Counter membuang pesan ini di hulu (reaction/status/sistem) - berhenti tanpa error.');
    return [];
  }
  // Input BERISI tapi tetap tanpa identitas = payload yang benar-benar asing.
  // Ini tetap harus berisik: bentuk payload Kirimi berubah tanpa kita tahu.
  throw new Error('Identitas user kosong (phone & lid tidak ada) - payload webhook tidak dikenal: ' + JSON.stringify(cc.body?.from ?? null));
}

let rows = [];
try {
  rows = $('Read User STATS').all().map(i => i.json).filter(r => r && Object.keys(r).length > 0);
} catch (e) { console.warn('Read User STATS tidak terbaca:', e.message); }

let row = null;
if (phone) row = rows.find(r => digits(r['No WA']) === phone) || null;
if (!row && lid) {
  row = rows.find(r => digits(r['lid']) === lid) || rows.find(r => digits(r['No WA']) === lid) || null;
}

const resolvedKey = row ? String(row['No WA']).trim() : (phone || lid);
const greetingSent = row ? String(row['greeting_sent'] || '').trim().toUpperCase() : '';
console.log('resolved_key=' + resolvedKey + ' | row_found=' + (!!row));

return [{
  json: {
    ...cc,
    resolved_key: resolvedKey,
    row_found: !!row,
    bot_mode: row ? String(row['bot_mode'] || '').trim().toUpperCase() : '',
    greeting_sent: greetingSent,
    is_new_user: !row || greetingSent !== 'Y',
    buffer_done_ts: Number(row ? (row['buffer_done_ts'] || 0) : 0) || 0,
    unit_interest: row ? String(row['unit_interest'] || '').trim() : '',
    unit_interest_ts: Number(row ? (row['unit_interest_ts'] || 0) : 0) || 0,
    budget_range: row ? String(row['budget_range'] || '').trim() : '',
    budget_range_ts: Number(row ? (row['budget_range_ts'] || 0) : 0) || 0,
    nama_lengkap: row ? String(row['nama_lengkap'] || '').trim() : '',
    nama_lengkap_ts: Number(row ? (row['nama_lengkap_ts'] || 0) : 0) || 0,
    lokasi_kerja: row ? String(row['lokasi_kerja'] || '').trim() : '',
lokasi_kerja_ts: Number(row ? (row['lokasi_kerja_ts'] || 0) : 0) || 0,
    pending_survey_tanggal: row ? String(row['pending_survey_tanggal'] || '').trim() : '',
    pending_survey_jam: row ? String(row['pending_survey_jam'] || '').trim() : '',
    pending_survey_unit: row ? String(row['pending_survey_unit'] || '').trim() : '',
    pending_survey_ts: Number(row ? (row['pending_survey_ts'] || 0) : 0) || 0,
    lead_source_db: row ? String(row['lead_source'] || '').trim() : '',
    userRow: row ? { ...row } : {},
    nama_bisnis: row ? String(row['nama_bisnis'] || '').trim() : '',
    industri: row ? String(row['industri'] || '').trim() : '',
    masalah_utama: row ? String(row['masalah_utama'] || '').trim() : '',
    masalah_utama_ts: Number(row ? (row['masalah_utama_ts'] || 0) : 0) || 0,
    volume_chat: row ? String(row['volume_chat'] || '').trim() : '',
    volume_chat_ts: Number(row ? (row['volume_chat_ts'] || 0) : 0) || 0,
    minat_paket: row ? String(row['minat_paket'] || '').trim() : '',
    minat_paket_ts: Number(row ? (row['minat_paket_ts'] || 0) : 0) || 0,
    deck_requested: row ? String(row['deck_requested'] || '').trim() : '',
    brief_terisi: row ? String(row['brief_terisi'] || '').trim() : '',
    bahasa: row ? String(row['bahasa'] || '').trim() : '',
    counter_db: Number(row ? (row['Counter'] || 0) : 0) || 0,
    // Teks balasan terakhir yang benar-benar sampai ke prospek (lihat P0-2 di
    // _patch_2026-09-05.py). Simple Memory menyimpan tulisan MENTAH AI Agent,
    // yang bisa berbeda dari yang dikirim. Kolom ini sumber kebenarannya.
    last_bot_reply: row ? String(row['last_bot_reply'] || '').trim() : '',
    last_bot_reply_ts: Number(row ? (row['last_bot_reply_ts'] || 0) : 0) || 0
  }
}];

// Rate Limiter - cegah spam, TAPI jangan menelan pesan prospek sungguhan.
// Node ini berdiri SEBELUM Append MSG_BUFFER: pesan yang ditolak di sini hilang
// permanen, tidak ikut debounce, tidak pernah dibaca AI. Batas lama (5/menit,
// hardcode) terlalu ketat untuk prospek iklan yang mengetik beruntun - pesan
// ke-6 lenyap tanpa jejak. Sekarang mengikuti CONFIG, default 15/menit.
const cfg = (() => { try { return $('Parse Config').first().json.config || {}; } catch (e) { return {}; } })();
const userWa = $('Resolve User Row').first().json.resolved_key;
const now = Date.now();

const maxMessages = Math.max(1, Number(cfg.rate_limit_max) || 15);
const windowMs    = Math.max(1000, (Number(cfg.rate_limit_window_sec) || 60) * 1000);

const staticData = $getWorkflowStaticData('global');
const rateLimits = staticData.rateLimits || {};
const userKey = 'rl_' + userWa;

if (!rateLimits[userKey] || (now - rateLimits[userKey].windowStart) > windowMs) {
  rateLimits[userKey] = { count: 1, windowStart: now };
} else {
  rateLimits[userKey].count++;
}

// Buang entri basi supaya static data tidak tumbuh tanpa batas seumur workflow.
for (const k of Object.keys(rateLimits)) {
  if ((now - rateLimits[k].windowStart) > windowMs * 60) delete rateLimits[k];
}
staticData.rateLimits = rateLimits;

if (rateLimits[userKey].count > maxMessages) {
  console.log('RATE LIMITED: ' + userWa + ' sudah ' + rateLimits[userKey].count
              + ' pesan dalam ' + (windowMs / 1000) + ' dtk');
  return [];
}

console.log('RATE OK: ' + userWa + ' pesan ke-' + rateLimits[userKey].count + '/' + maxMessages);
return [$input.first()];

// ============================================================
// HUMAN-IN-THE-LOOP CHECK — bot_mode 'OFF' = admin pegang manual, bot berhenti.
// Sumbernya Resolve User Row, bukan pembacaan STATS tersendiri: node lama
// 'Read STATS for HITL' membaca ulang seluruh tab ~2 detik setelah
// 'Read User STATS', untuk nilai yang tidak berubah di antara keduanya.
// Pemeriksaan ulang yang berarti tetap ada, setelah debounce, di
// 'Re-Read STATS Debounce'.
// ============================================================
const r = $('Resolve User Row').first().json;
const botMode = String(r.bot_mode || '').trim().toUpperCase();

if (botMode === 'OFF') {
  console.log('👨‍💼 HITL AKTIF — admin sedang handle manual, bot berhenti.');
  return [];
}

console.log(`🤖 Bot mode AKTIF (bot_mode="${botMode}") — lanjut.`);
return [$input.first()];

// NODE: Cek_user_status
// ====================================================================
// CEK_USER_STATUS - gate HITL post-debounce + gabung MSG_BUFFER +
// siapkan SYSTEM_DATA (intro user baru, unit/budget tersimpan).
// Perubahan 2026-07-17: (1) INTRO "Saya VIRA" -> "Saya Vira",
// (2) inject TANGGAL_SEKARANG (WIB) ke [SYSTEM_DATA].
// [V2 - VISION] 2026-08-07: baris MSG_BUFFER yang isinya HANYA media
// (message kosong) TIDAK lagi dibuang. URL gambar dalam window debounce
// dikumpulkan ke `vision_images` untuk dianalisa Claude Haiku.
// ====================================================================
const cc = $('Chat Counter').first().json;
const resolve = $('Resolve User Row').first().json;
const resolvedKey = resolve.resolved_key;
const cfg = (() => { try { return $('Parse Config').first().json.config || {}; } catch (e) { return {}; } })();

const debounceItem = $('Re-Read STATS Debounce').first();
const debounceRow = (debounceItem && debounceItem.json) ? debounceItem.json : {};
const botModeNow = String(debounceRow['bot_mode'] || '').trim().toUpperCase();
if (botModeNow === 'OFF') {
  console.log('HITL (post-debounce): bot_mode OFF - berhenti, admin handle manual.');
  return [];
}

const doneTs = Number(debounceRow['buffer_done_ts'] || 0) || 0;
const myTs = Number(cc.process_start_ts) || 0;
let bufRows = [];
try {
  bufRows = $('Read MSG_BUFFER').all().map(i => i.json).filter(r => !!r);
} catch (e) { console.warn('Read MSG_BUFFER tidak terbaca:', e.message); }

const MAX_AGE_MS = 30 * 60 * 1000;
// [V2] baris dianggap valid kalau punya teks ATAU punya media.
let msgs = bufRows
  .map(r => ({
    ts: Number(r.ts) || 0,
    message: String(r.message ?? '').trim(),
    media_url: String(r.media_url ?? '').trim(),
    media_type: String(r.media_type ?? '').trim().toLowerCase()
  }))
  .filter(r => r.ts > doneTs && r.ts <= myTs && (myTs - r.ts) < MAX_AGE_MS)
  .filter(r => r.message !== '' || (r.media_url !== '' && r.media_type === 'image') || r.media_type === 'other')
  .sort((a, b) => a.ts - b.ts);

// Fallback: buffer gagal dibaca / kolom media belum ada -> pakai pesan ini saja.
if (!msgs.length) {
  const fb = {
    ts: myTs,
    message: String(cc.original_message || '').trim(),
    media_url: String(cc.media_url || '').trim(),
    media_type: String(cc.media_kind || 'none')
  };
  if (fb.message !== '' || fb.media_url !== '' || fb.media_type === 'other') msgs = [fb];
}

const userMessage = msgs.map(r => r.message).filter(Boolean).join('\n');

// [V2] kumpulkan gambar dalam window ini (dedup URL, ambil yang terbaru)
const maxImg = Math.max(1, Number(cfg.vision_max_images ?? 3) || 3);
const seenUrl = new Set();
const allImages = [];
for (const r of msgs) {
  if (r.media_type === 'image' && r.media_url && !seenUrl.has(r.media_url)) {
    seenUrl.add(r.media_url);
    allImages.push({ url: r.media_url, ts: r.ts });
  }
}
const visionImages = allImages.slice(-maxImg);
const imagesDropped = Math.max(0, allImages.length - visionImages.length);
const otherMediaCount = msgs.filter(r => r.media_type === 'other').length;
const hasImage = visionImages.length > 0;
// [V2.1] hanya mode 'full' yang memanggil Claude. 'ack'/'off' = nol biaya.
const visionMode = String(cfg.vision_mode || 'full').toLowerCase();
const visionOn = hasImage && visionMode === 'full';

// Teks yang dilihat AI di [USER QUERY]. Kalau user cuma kirim lampiran tanpa
// caption, JANGAN pakai kata "gambar"/"foto" di sini - regex wantsMedia di
// Preprocess akan kena dan Vira malah kirim brosur.
const userQueryText = userMessage !== ''
  ? userMessage
  : ((hasImage || otherMediaCount > 0) ? '(user mengirim lampiran tanpa teks)' : '');

const greetingSent = String(debounceRow['greeting_sent'] || resolve.greeting_sent || '').trim().toUpperCase();
const isNewUser = greetingSent !== 'Y';

const TTL_S = 60 * 86400;
const nowS = Math.floor(Date.now() / 1000);
const uiTs = Number(debounceRow['unit_interest_ts'] || resolve.unit_interest_ts || 0) || 0;
const uiFresh = uiTs > 0 && (nowS - uiTs) <= TTL_S;
const unitInterest = uiFresh ? String(debounceRow['unit_interest'] || resolve.unit_interest || '').trim() : '';
const brTs = Number(debounceRow['budget_range_ts'] || resolve.budget_range_ts || 0) || 0;
const brFresh = brTs > 0 && (nowS - brTs) <= TTL_S;
const budgetRange = brFresh ? String(debounceRow['budget_range'] || resolve.budget_range || '').trim() : '';

// PROFIL USER (nama lengkap + lokasi_kerja)
const namaLengkap = String(debounceRow['nama_lengkap'] || resolve.nama_lengkap || '').trim();
const lokasi_kerja     = String(debounceRow['lokasi_kerja']     || resolve.lokasi_kerja     || '').trim();
const needName     = !namaLengkap;
const needDomicile = !lokasi_kerja;
const askProfileNow = isNewUser && (needName || needDomicile);
const askProfileTarget = !askProfileNow ? 'NO'
  : (needName && needDomicile) ? 'nama+lokasi_kerja'
  : (needName ? 'nama' : 'lokasi_kerja');
const needUnit = !unitInterest || unitInterest === 'UNKNOWN';
const askUnitNow = isNewUser && needUnit;
const askUnitTarget = askUnitNow ? 'tipe unit (subsidi/komersial)' : 'NO';

// PENDING SURVEY (register #1) - slot survey lintas giliran dari STATS, TTL 48 jam.
const PENDING_TTL_S = 48 * 3600;
const psTs = Number(debounceRow['pending_survey_ts'] || resolve.pending_survey_ts || 0) || 0;
const psFresh = psTs > 0 && (nowS - psTs) <= PENDING_TTL_S;
const psTgl = psFresh ? String(debounceRow['pending_survey_tanggal'] || resolve.pending_survey_tanggal || '').trim() : '';
const psJam = psFresh ? String(debounceRow['pending_survey_jam'] || resolve.pending_survey_jam || '').trim() : '';
const psUnit = psFresh ? String(debounceRow['pending_survey_unit'] || resolve.pending_survey_unit || '').trim() : '';
const hasPendingSurvey = !!(psTgl || psJam || psUnit);

// Tanggal & jam sekarang dlm WIB - sumber kebenaran tanggal utk AI.
const nowWIB = new Date(new Date().toLocaleString('en-US', { timeZone: 'Asia/Jakarta' }));
const pad2 = n => String(n).padStart(2, '0');
const HARI = ['Minggu', 'Senin', 'Selasa', 'Rabu', 'Kamis', 'Jumat', 'Sabtu'];
const tanggalSekarang = `${nowWIB.getFullYear()}-${pad2(nowWIB.getMonth() + 1)}-${pad2(nowWIB.getDate())}`;
const hariSekarang = HARI[nowWIB.getDay()];
const jamSekarang = `${pad2(nowWIB.getHours())}:${pad2(nowWIB.getMinutes())}`;

// -- JARING PENGAMAN INGATAN (2026-09-05) --
// Simple Memory menyimpan tulisan MENTAH AI Agent. Kalau Process All mengganti
// teksnya (file tidak ada di katalog, pilihan media ambigu), atau kalau n8n
// restart dan memory hilang, model tidak tahu apa yang sebenarnya dibaca
// prospek - dia menyangkal pernah bertanya lalu bertanya ulang. Kolom STATS
// last_bot_reply selalu berisi teks yang BENAR-BENAR terkirim, jadi kebenaran
// itu selalu ada di prompt apa pun yang terjadi pada memory.
const lastReply = String(debounceRow['last_bot_reply'] || resolve.last_bot_reply || '').trim();
const lastReplyTs = Number(debounceRow['last_bot_reply_ts'] || resolve.last_bot_reply_ts || 0) || 0;
const lastReplyFresh = lastReply !== '' && lastReplyTs > 0 && (nowS - lastReplyTs) <= 24 * 3600;
const blokBalasanTerakhir = lastReplyFresh
  ? `\nBALASAN TERAKHIRMU YANG BENAR-BENAR DITERIMA PROSPEK:\n"${lastReply.replace(/"/g, "'").slice(0, 700)}"\n`
    + `Pesan prospek di bawah adalah tanggapan atas kalimat itu. Kalau ingatanmu berbeda, kalimat di atas yang benar.\n`
  : '';

const aiSystemData = `[SYSTEM_DATA]
USER_WA: ${resolvedKey}
IS_NEW_USER: ${isNewUser}
NAMA_LENGKAP: ${namaLengkap || 'UNKNOWN'}
TANGGAL_SEKARANG: ${tanggalSekarang} (${hariSekarang}) ${jamSekarang} WIB
${blokBalasanTerakhir}
CRITICAL INSTRUCTION:
${isNewUser
  ? 'USER BARU. Buka dengan perkenalan sesuai bagian PERKENALAN di instruksimu — susun dengan kalimatmu sendiri, jangan disalin persis, lalu gabungkan dengan jawaban atas pertanyaannya dalam SATU pesan.'
  : 'User lama. JANGAN memperkenalkan diri lagi, lanjutkan percakapan secara natural.'}

[USER QUERY]
${userQueryText}`;

return [{
  json: {
    ...cc,
    resolved_key: resolvedKey,
    ai_input_text: aiSystemData,
    user_message_final: userMessage,
    is_new_user: isNewUser,
    unit_interest_db: unitInterest,
    budget_range_db: budgetRange,
    nama_lengkap_db: namaLengkap,
    lokasi_kerja_db: lokasi_kerja,
    pending_survey_tanggal_db: psTgl,
    pending_survey_jam_db: psJam,
    pending_survey_unit_db: psUnit,
    ask_profile: askProfileTarget,
    buffer_done_ts_old: doneTs,
    last_bot_reply_prev: lastReply,
    last_bot_reply_fresh: lastReplyFresh,
    // ---- [V2 VISION] ----
    vision_images: visionImages,
    vision_images_dropped: imagesDropped,
    has_image: hasImage,
    vision_on: visionOn,
    other_media_count: otherMediaCount,
    user_query_text: userQueryText,
    vision_mode: visionMode
  }
}];

// ====================================================================
// DETECT LEAD SOURCE (BARU) — deteksi sumber traffic dari pesan pertama.
// Rule-based murah; default "Organik". Tulis sekali (preserve first-touch).
// ====================================================================
// [V2 VISION] baca dari INPUT, bukan langsung dari Cek_user_status.
// Node 'Rakit Konteks Gambar' menyisipkan deskripsi gambar ke ai_input_text;
// kalau di sini masih ambil dari Cek_user_status, sisipan itu ketimpa.
const pre = $input.first().json;
const resolve = $('Resolve User Row').first().json;
const cfg = (() => { try { return $('Parse Config').first().json.config || {}; } catch(e){ return {}; } })();
const firstMsg = String(pre.user_message_final || pre.original_message || '').toLowerCase();

const DEFAULT_MAP = [
  { source:'Instagram', keywords:['instagram','ig','insta','dari ig','lihat di ig','story ig'] },
  { source:'Facebook',  keywords:['facebook','fb','dari fb','lihat di fb','marketplace'] },
  { source:'Google',    keywords:['google','search','nyari di google','gmaps','maps'] },
  { source:'TikTok',    keywords:['tiktok','tt','dari tiktok'] },
  { source:'WhatsApp',  keywords:['broadcast','wa blast','katalog wa'] },
];
const MAP = (Array.isArray(cfg.lead_source_map) && cfg.lead_source_map.length) ? cfg.lead_source_map : DEFAULT_MAP;

// 2026-09-05: dulu memakai includes() telanjang, jadi kata pendek mencocoki
// bagian tengah kata lain - 'ig' kena di "tinggi"/"bagi"/"ingin", 'tt' kena di
// "watt". Sumber lead jadi salah, dan angka itu yang dipakai menilai iklan.
// Kata <= 3 huruf sekarang wajib berdiri sendiri; kata panjang tetap longgar.
const esc = (s) => String(s).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const cocokKata = (teks, kw) => {
  const k = String(kw).toLowerCase().trim();
  if (!k) return false;
  const pola = k.length <= 3
    ? new RegExp('(^|[^a-z0-9])' + esc(k) + '([^a-z0-9]|$)', 'i')
    : new RegExp(esc(k), 'i');
  return pola.test(teks);
};

let detected = '';
for (const m of MAP) {
  const kws = (m.keywords || []);
  if (kws.some(k => cocokKata(firstMsg, k))) { detected = m.source; break; }
}
if (!detected) detected = 'Organik';

const existing = String(resolve.lead_source_db || '').trim();
const finalSource = existing || detected;   // preserve sumber pertama

return [{ json: { ...pre, lead_source_detected: detected, lead_source_final: finalSource } }];

// ============================================
// PREPROCESS - CONTEXT DETECTION - VIRA Steven (v3, 2026-09-05)
//
// Versi lama masih memakai regex domain PROPERTI warisan Persada (tipe unit, KPR,
// survey lokasi, legalitas, fasilitas). Di bot jasa AI customer service tiga di
// antaranya aktif merusak:
//
//   1. `wantsSurvey || mentionsDateTime` menyuntikkan kalimat yang mendorong
//      [TALK_TO_ADMIN]. Tag itu MEMATIKAN bot untuk orang tersebut sampai
//      bot_mode dinyalakan manual. mentionsDateTime kena di "senin", "besok",
//      "jam 10", "minggu" - kata yang wajar muncul saat prospek menjawab
//      pertanyaan galian ("paling ramai hari Senin", "mau mulai bulan depan").
//      Untuk nomor iklan, itu artinya lead membunuh dirinya sendiri.
//   2. `wantsMedia` kena kata "gambar"/"foto" - termasuk saat PROSPEK yang
//      mengirim gambar - lalu Vira ikut mengirim brosur yang tidak diminta.
//   3. `askingPrice` kena kata "berapa" telanjang, termasuk saat prospek MENJAWAB
//      ("kira-kira berapa chat per hari?" -> "20an"), lalu konteks harga
//      disuntikkan di giliran yang tidak ada hubungannya dengan harga.
//
// Kode properti sisanya (units, budgetMention, KPR, lokasi, legalitas, fasilitas,
// kalender survey) dibuang - tidak ada satu node pun yang membacanya. Hanya
// askingPrice & wantsMedia yang dipakai di luar node ini (boost FAQ Retrieve).
// ============================================
const json = $input.item.json;
const fullMessage = json.ai_input_text || json.message || json.text || '';

// -- PARSE INPUT --
let actualUserMessage = '';
if (fullMessage.includes('[USER QUERY]')) {
  actualUserMessage = (fullMessage.split('[USER QUERY]')[1] || '').trim();
} else {
  actualUserMessage = String(fullMessage).trim();
}

let isNewUser = false;
if (fullMessage.includes('[SYSTEM_DATA]')) {
  const m = fullMessage.match(/IS_NEW_USER:\s*(\w+)/i);
  if (m) isNewUser = m[1].toLowerCase() === 'true';
}

const message = actualUserMessage.toLowerCase();
const userPhone = json.user_wa || json.from || 'unknown';

// -- INTENT (domain jasa AI customer service) --
// Harus ada kata yang benar-benar soal uang/paket, bukan sekadar "berapa".
// Akhiran -nya/-ku/-mu WAJIB ditoleransi: \b di ujung kata membuat "harganya",
// "brosurnya", "biayanya" tidak pernah cocok - padahal itu bentuk yang paling
// sering dipakai orang Indonesia saat bertanya.
//
// 2026-09-07 - insiden studysipil. Kata harga TELANJANG tidak cukup lagi.
// Debounce menggabungkan empat pesan jadi satu: "biasanya pas lg promo buka
// kelas sih / ads itu pasti pd tanya hal yg sama / harga, kuota, apa aja yg
// didapet / sama jadwalnya kapan". Dua kata kena (`promo` dan `harga`) padahal
// dua-duanya milik PELANGGAN DIA. Flag menyala -> aiContext menyuntik "User
// menanyakan harga. Sebut kisaran..." tepat di atas [USER QUERY] -> VIRA
// menyebut Rp3jt/Rp5jt ke lead yang belum bertanya, dan balasan berikutnya
// minta diskon. Aturan di system prompt tidak menolong: dari sudut pandang
// model, konteks ini MEMBERI TAHU bahwa syarat "kalau ditanya" sudah terpenuhi.
//
// `promo` dan `bayar` dicabut dari daftar: dua-duanya jauh lebih sering muncul
// saat prospek bercerita soal bisnisnya sendiri ("lagi promo buka kelas",
// "pelanggan bayar transfer") daripada saat dia menanyakan harga kita.
const KATA_HARGA = /\b(harga|hrg|biaya|tarif|langganan|paket|basic|premium|mahal|murah|diskon|setup ?fee|nego|price ?list|pricelist)(nya|ku|mu)?\b/i;

// Dia sedang MENCERITAKAN pertanyaan pelanggannya, bukan bertanya ke kita.
const CERITA_ORANG_LAIN =
     /\b(pd|pada|mereka|orang|customer|pelanggan|calon|murid|klien|konsumen|pembeli|user|tamu|pasien)\b[^.?!]{0,30}\b(tanya|nanya|nanyain|bertanya|tanyain)\b/i.test(message)
  || /\b(tanya|nanya|ditanya|ditanyain|nanyain|pertanyaan|pertanyaannya)\b[^.?!]{0,30}\b(sama|hal|berulang|melulu|itu.?itu|terus)\b/i.test(message)
  || /\b(sering|selalu|biasanya|pasti|kebanyakan|rata.?rata)\b[^.?!]{0,25}\b(tanya|nanya|nanyain|ditanya|ditanyain)\b/i.test(message);

// Angka itu MILIK DIA - jawaban atas pertanyaan TINGKAT 2B, bukan pertanyaan
// harga. Tanpa gerbang ini, tiap kali prospek menjawab "biaya adminku 3 juta"
// atau "sekali closing 500rb" konteks harga ikut menyala di giliran itu.
const MILIK_DIA =
     /\b(paket|harga|biaya|tarif|admin)\w*\b[^.?!]{0,20}\b(aku|gue|gw|saya|kami|kita|sendiri)\b/i.test(message)
  || /\b(paket|harga|biaya|tarif|kelas|admin)\w*ku\b/i.test(message)
  || /\b(biaya|harga|tarif)\b[^.?!]{0,15}\b\w+ku\b/i.test(message);

// Pengaman balik: kalau di pesan yang sama dia JELAS menanyakan harga KITA,
// cerita soal pelanggannya tidak boleh membungkam. Debounce sering menggabung
// dua-duanya dalam satu giliran.
const TANYA_HARGA_KITA =
     /\b(berapa|brp)\b[^.?!]{0,25}\b(harga|biaya|tarif|paket|basic|premium|langganan)/i.test(message)
  || /\b(harga|biaya|tarif|paket|basic|premium|langganan)(nya|ku|mu)?\b[^.?!]{0,25}\b(berapa|brp|gimana|bagaimana)\b/i.test(message)
  || /\b(harga|biaya|tarif|paket|price ?list|pricelist)(nya|mu)?\b[^.?!]{0,20}\b(vira|kamu|kalian|lo|situ|steven)\b/i.test(message)
  || /\b(vira|kamu|kalian|paket)\w*\b[^.?!]{0,20}\b(harga|biaya|tarif)(nya|mu)?\b/i.test(message);

// ── JAWABAN ATAS PERTANYAANKU (2026-09-23, v3.13) ──
// Uji Steven 2026-09-23 13:41 ("Rehan", sewa raket padel). VIRA bertanya "Dari chat sampai
// akhirnya jadi sewa, biasanya lewat langkah apa aja kak?", dia menjawab "harga dulu, trs klo
// udah aman baru ke payment". Kata `harga` di situ bagian ALUR PENJUALANNYA - tapi tidak ada kata
// tanya pelanggan (CERITA_ORANG_LAIN) dan bukan angka miliknya (MILIK_DIA), jadi konteks harga
// menyala. VIRA lalu mengutip catatan itu ("Oh itu alur bisnis kakak yang dia ceritakan kak,
// bukan nanya harga VIRA") dan tetap menyebut Basic/Premium tanpa ditanya.
// Gerbang ketiga: pesan ini MENJAWAB pertanyaanku soal alur penjualannya, atau soal apa yang biasa
// ditanyakan pelanggannya (uji 21/09 Jacob: "Harga sewa, cara sewa, ongkir berapa"). Sumbernya
// kalimat tanya di last_bot_reply - teks yang BENAR-BENAR terkirim. Pesan yang memuat "?" tidak
// pernah dianggap jawaban, dan pertanyaan yang jelas ditujukan ke kita ("harga vira berapa",
// "paket kalian") tetap menyalakan konteks harga. Pertanyaanku yang menawarkan penjelasan
// ("mau aku jelasin alur kerja VIRA?") bukan pertanyaan alur penjualannya.
const BALASAN_LALU = (() => {
  try { return String($('Resolve User Row').first().json.last_bot_reply || '').toLowerCase(); }
  catch (e) { return ''; }
})();
const TANYA_LALU = BALASAN_LALU.match(/[^.?!\n]+\?/g) || [];
const tanyaAlur = (k) => /\b(langkah|alur|tahap)\w*\b|\bsampai\s+(jadi|akhirnya)\b/.test(k)
  && /\b(biasanya|pelanggan|customer|pembeli|calon|closing)\b|\bdari\s+chat\b|\bchat\s+(pertama|masuk)\b|\bsampai\s+(jadi|akhirnya)\b/.test(k)
  && !/\b(vira|jelas\w*)\b/.test(k);
const tanyaPertanyaanPelanggan = (k) =>
     /\b(sering|paling|biasanya|banyak)\b[^?]{0,25}\bditanya\w*/.test(k)
  || /\b(pelanggan|customer|pembeli|konsumen|klien|calon|mereka|orang|murid|pasien|penyewa)\w*\b[^?]{0,30}\b(nanya|tanya)\w*/.test(k)
  || /\bpertanyaan\w*\b[^?]{0,25}\b(sering|tersering|paling)\b/.test(k);
const JAWAB_PERTANYAANKU = !/\?/.test(message)
  && TANYA_LALU.some(k => tanyaAlur(k) || tanyaPertanyaanPelanggan(k));
const MENYEBUT_KITA = /\b(vira|kamu|kalian|lo|lu|situ|steven)\b/.test(message);
const BUKAN_TANYA_HARGA = CERITA_ORANG_LAIN || MILIK_DIA || JAWAB_PERTANYAANKU;

const askingPrice = (TANYA_HARGA_KITA && !(JAWAB_PERTANYAANKU && !MENYEBUT_KITA))
  || (KATA_HARGA.test(message) && !BUKAN_TANYA_HARGA)
  || (/\bberapa\b[^?]{0,20}\b(harga|biaya|duit|rupiah|bulan|bulanan)/i.test(message)
      && !BUKAN_TANYA_HARGA);
// Pesan menyebut harga, tapi gerbang di atas memutuskan dia TIDAK menanyakan harga VIRA.
// Process All memakainya untuk membuang kalimat harga VIRA yang tidak ditanya (v3.13).
const hargaBukanTanya = !askingPrice && (KATA_HARGA.test(message)
  || /\bberapa\b[^?]{0,20}\b(harga|biaya|duit|rupiah|bulan|bulanan)/i.test(message));

// File hanya dianggap DIMINTA kalau ada kata bendanya DAN kata memintanya.
// "aku kirim foto ya" -> BENDA tidak kena (foto sengaja tidak masuk daftar).
const BENDA_FILE = /\b(brosur|katalog|price ?list|portfolio|portofolio|deck|demo|dokumen|file|contoh)(nya|ku|mu)?\b/i;
const KATA_MINTA = /\b(minta|kirim|kirimin|share|bagi|boleh|ada|punya|lihat|liat|mau|pengen|bisa|dong)\b/i;
const wantsMedia = BENDA_FILE.test(message) && KATA_MINTA.test(message);

// Niat bicara langsung dengan Steven. SENGAJA TIDAK disuntikkan sebagai dorongan
// tag - hanya dicatat, supaya Process All yang memutuskan apakah bot dimatikan.
const wantsHuman = /\b(telp|telepon|telfon|call|ditelpon|ditelepon|ketemu|meeting|zoom|gmeet|disambungkan|sambungin)\b/i.test(message)
  || /\b(hubungi|kontak|nomor|no\.?|cp|wa)\b[^.?!]{0,25}steven/i.test(message)
  || /\bhubungi\b[^.?!]{0,20}\b(aku|saya|gue|gw)\b/i.test(message)
  || /\b(ngobrol|bicara|tanya|chat|ngomong)\b[^.?!]{0,20}(langsung|steven|orangnya|manusia|orang aslinya)/i.test(message);

let aiContext = '';
// 2026-09-23 (v3.13): + alur penjualan, dan larangan mengutip catatan ini - model sempat menulis
// "Oh itu alur bisnis kakak yang dia ceritakan kak, bukan nanya harga VIRA" ke prospek.
if (askingPrice) aiContext += 'Sepertinya dia menanyakan harga. Periksa dulu pesannya: kalau dia memang menanyakan harga VIRA, sebut kisaran dari DATA PRODUK lalu arahkan ke Steven untuk angka final. Kalau kata harga muncul karena dia sedang menceritakan pertanyaan pelanggannya sendiri, alur penjualannya ("harga dulu, terus transfer"), atau angka bisnisnya sendiri, JANGAN sebut angka apa pun dan jangan menyinggung harga VIRA sama sekali. Jangan menawar, jangan memberi diskon. Catatan ini hanya untukmu: jangan dikutip, jangan dikomentari di balasan. ';
if (wantsMedia)  aiContext += 'User meminta file. Kalau ada yang cocok di DAFTAR MEDIA, pasang [SEND_MEDIA: <nama-link>] persis seperti tertulis di daftar. Kalau tidak ada yang cocok, jangan pasang tag apa pun dan jangan mengarang nama link. ';

// -- RAKIT INPUT AI --
let systemDataBlock = '';
if (fullMessage.includes('[USER QUERY]')) systemDataBlock = fullMessage.split('[USER QUERY]')[0].trim();

let enhancedInput = '';
if (systemDataBlock) enhancedInput += systemDataBlock + '\n\n';
if (aiContext.trim()) enhancedInput += '[CONTEXT: ' + aiContext.trim() + ']\n\n';
enhancedInput += '[USER QUERY]\n' + actualUserMessage;

return {
  userPhone,
  actualUserMessage,
  fullMessage,
  messageLower: message,
  isNewUser,
  askingPrice,
  hargaBukanTanya,
  wantsMedia,
  wantsHuman,
  aiContext: aiContext.trim(),
  ai_input_text: enhancedInput
};

// ===== FAQ RETRIEVE — VIRA Steven =====
// Pencarian FAQ leksikal (TF-IDF sederhana + sinonim domain).
// Sumber datanya `katalog` dari cache, bukan $('Read FAQ') langsung: saat cache HIT
// node Sheets-nya tidak dijalankan sama sekali.
// Blok `data_context` warisan Persada dibuang — isinya dibangun dari $('Read PRODUK Data')
// yang sudah tidak ada sejak node itu direname, jadi selalu kosong, dan tidak ada satu
// node pun yang membacanya (Rakit Konteks menyusun program_context & links_context sendiri).
try {
  const inp = $input.first().json;
  const pre = $('Preprocess - Context Detection').first().json;
  const query = pre.actualUserMessage || '';
  const katalog = inp.katalog || { faq: [] };

  const STOP = new Set(['yang','untuk','dan','di','ke','dari','itu','ini','apa','apakah','bisa','kah','ya','yaa','kak','min','dong','sih','kok','aja','ada','gimana','bagaimana','saya','aku','nya','kalau','atau','juga','sudah','belum','mau','dengan','pada','adalah','tolong','mohon','halo','hai','permisi','terima','kasih','sama','buat','soal','tentang','nih','ga','gak','engga','tidak','dll','yg','utk','kamu','kita','gitu','banget','emang','memang']);

  // Kelompok sinonim domain VIRA Steven (jasa AI customer service), bukan properti.
  // Kata pertama tiap grup jadi wakilnya.
  const GROUPS = [
    ['harga','biaya','tarif','bayar','paket','basic','premium','langganan','bulanan','mahal','murah','budget','nego','setup','token','kontrak','berhenti'],
    ['fitur','kemampuan','fungsi','follow','followup','laporan','analitik','invoice','jadwal','multibahasa','inggris','mandarin'],
    ['media','foto','gambar','video','brosur','katalog','file','dokumen','demo','contoh','bukti','portfolio','tangkapan'],
    ['aman','keamanan','privasi','bocor','rahasia','akses','data'],
    ['proses','lama','durasi','waktu','golive','mulai','siapkan','persiapan','maintenance'],
    ['deck','pitch','proposal','penawaran','presentasi'],
    ['steven','klien','pengalaman','siapa','background','qa'],
    ['whatsapp','wa','nomor','device','aplikasi','install','internet','server','sheets','spreadsheet'],
    ['error','gangguan','down','mati','rusak','gagal','ramai','lonjakan','kuat'],
    ['bot','ai','robot','manusia','admin','chatbot','template','persona','gaya'],
  ];
  const SYN = {}; for (const g of GROUPS) for (const w of g) SYN[w] = g[0];

  const stem = (t) => { let w = t; for (const s of ['nya','kah','lah','kan','an','i']) if (w.length - s.length >= 4 && w.endsWith(s)) { w = w.slice(0, -s.length); break; } for (const p of ['meng','meny','mem','men','peng','peny','pem','pen','ber','ter','di','se','ke','me','pe']) if (w.length - p.length >= 4 && w.startsWith(p)) { w = w.slice(p.length); break; } return w; };
  const tok = (s) => (s || '').toLowerCase().replace(/[^\p{L}\p{N}\s]/gu, ' ').split(/\s+/).filter(Boolean).filter(t => !STOP.has(t)).map(t => { const a = SYN[t]; if (a) return a; const st = stem(t); return SYN[st] || st; }).filter(t => t.length >= 2 && !STOP.has(t));

  const faq = (katalog.faq || []).filter(r => r && r.Pertanyaan && r.Jawaban
    && /^\s*(aktif|active|on|ya)\s*$/i.test(String(r.Status || 'Aktif')));
  const docs = faq.map(r => ({ row: r, toks: tok(r.Pertanyaan) }));
  const Nn = docs.length, df = {};
  for (const dd of docs) for (const t of new Set(dd.toks)) df[t] = (df[t] || 0) + 1;
  const idf = (t) => Math.log((Nn + 1) / ((df[t] || 0) + 1)) + 1;

  // Boost mengikuti nama Kategori yang benar-benar ada di tab FAQ VIRA Steven.
  const boost = {};
  if (pre.askingPrice) boost['Harga'] = 1.25;
  if (pre.wantsMedia)  boost['Fitur'] = 1.15;

  const qToks = [...new Set(tok(query))];
  let faq_context = '';
  if (qToks.length && docs.length) {
    const scored = docs.map(dd => {
      const dset = new Set(dd.toks);
      let s = 0, m = 0;
      for (const t of qToks) if (dset.has(t)) { s += idf(t); m++; }
      s *= (boost[dd.row.Kategori] || 1.0);
      return { row: dd.row, score: s, matched: m };
    }).sort((a, b) => b.score - a.score);
    const top = scored[0];
    const FLOOR = 2.5, needCov = qToks.length >= 3 ? 2 : 1;
    if (top.score >= FLOOR && top.matched >= needCov) {
      const kept = scored.filter(x => x.score >= 0.45 * top.score && x.matched >= 1).slice(0, 4);
      faq_context = kept.map(x => `Q: ${x.row.Pertanyaan}\nA: ${x.row.Jawaban}`).join('\n\n');
    }
  }

  return [{ json: { ...pre, katalog, faq_context }, pairedItem: { item: 0 } }];
} catch (e) {
  const pre = ($('Preprocess - Context Detection').first() || { json: {} }).json || {};
  const katalog = ($input.first().json || {}).katalog || { faq: [], program: [], links: [], about: [] };
  return [{ json: { ...pre, katalog, faq_context: '', faq_error: String(e) }, pairedItem: { item: 0 } }];
}

// ── Process All — VIRA Steven ──
// Ditulis ulang dari versi Persada oleh _transform.py. Jangan diedit langsung di n8n.
const item = $input.first();
let aiOutput = '';
if (item?.json?.content && Array.isArray(item.json.content) && item.json.content.length > 0) {
  aiOutput = item.json.content[0].text || '';
} else {
  aiOutput = item?.json?.output || item?.json?.text || '';
}
console.log('AI Output preview:', aiOutput.substring(0, 300));

const chatCounter = $('Chat Counter').first().json;
const preprocess  = $('Preprocess - Context Detection').first().json;
const cfg  = (() => { try { return $('Parse Config').first().json.config || {}; } catch (e) { return {}; } })();
const prev = (() => { try { return $('Resolve User Row').first().json || {}; } catch (e) { return {}; } })();
const originalMessage = chatCounter.original_message || '';
const isNewUser = preprocess?.isNewUser || false;

// ── util ──
// buang karakter kontrol, rapikan spasi, batasi panjang
const BERSIH = (s, max) => String(s ?? '')
  .split('').filter(ch => ch.charCodeAt(0) >= 32).join('')
  .replace(/\s+/g, ' ').trim().slice(0, max || 200);
// nilai yang artinya "tidak ada isi" — termasuk placeholder yang diminta ke AI
const KOSONG = (s) => {
  const t = BERSIH(s).toLowerCase().replace(/[.\s]+$/, '');
  return !t || t === '-' || t === '...' || t === 'belum disebut' || t === 'belum tahu'
      || t === 'tidak disebut' || t === 'n/a' || t === 'na' || t === 'null' || t === 'undefined';
};
// Drive 'uc?export=download' membalas halaman konfirmasi virus-scan (HTML) untuk
// file besar, bukan byte filenya. Bentuk usercontent + confirm=t melewati halaman itu.
// 2026-09-05: dipindah ke lingkup atas. Sebelumnya const ini hidup di dalam blok
// `if (isSendMedia)` tapi dipanggil lagi di blok MEDIA KE-2 di luar blok itu ->
// ReferenceError setiap kali balasan memuat dua tag [SEND_MEDIA] yang keduanya
// ketemu di LINKS. Akibatnya prospek tidak menerima balasan sama sekali.
const rapikanUrl = (u) => {
  const s = String(u || '').trim();
  const m = s.match(/^https?:\/\/(?:drive|docs)\.google\.com\/(?:uc\?(?:[^#]*&)?id=|file\/d\/)([A-Za-z0-9_-]{10,})/);
  return m ? ('https://drive.usercontent.google.com/download?id=' + m[1] + '&export=download&confirm=t') : s;
};

// ── TAG sederhana ──
let isTalkToAdmin   = aiOutput.includes('[TALK_TO_ADMIN]');
// Ditandai true setiap kali teks yang dikirim ke prospek BUKAN tulisan AI.
// Dua kasus yang tersisa (media ambigu & file tidak ada di katalog) memang harus
// mengganti kalimat, karena AI menjanjikan file yang tidak bisa dikirim.
// Desinkronisasi ingatannya ditutup dari sisi lain: kolom STATS last_bot_reply
// selalu berisi teks final, dan Cek_user_status menyuntikkannya ke prompt.
let replyOverridden = false;
const isUnknown     = aiOutput.includes('[UNKNOWN]');

// ── TAG: [SEND_MEDIA: key] — maksimal 2, tanpa fallback frasa ──
let isSendMedia = false, mediaKey = '';
const mediaKeysAll = [...new Set(
  [...aiOutput.matchAll(/\[\s*SEND_MEDIA\s*(?::\s*([^\]]*))?\]/gi)]
    .map(m => (m[1] || '').trim().toLowerCase())
    .filter(Boolean)
)].slice(0, 2);
if (mediaKeysAll.length) { isSendMedia = true; mediaKey = mediaKeysAll[0]; }

// ── TAG: [FACTS ...] + merge persist ──
const FACT_FIELDS = ['nama_lengkap', 'nama_bisnis', 'industri', 'masalah_utama',
                     'volume_chat', 'budget_range', 'minat_paket'];
const PANJANG = { masalah_utama: 300, nama_lengkap: 60 };
const factsMatch = aiOutput.match(/\[\s*FACTS\b([^\]]*)\]/i);
const facts = {};
if (factsMatch && factsMatch[1]) {
  const isi = factsMatch[1];
  for (const f of FACT_FIELDS) {
    const m = isi.match(new RegExp(f + '\\s*=\\s*"([^"]*)"', 'i'));
    if (m) facts[f] = m[1];
  }
  // alias: prompt versi awal memakai nama="..." untuk nama_lengkap
  const mn = isi.match(/(^|[\s\[])nama\s*=\s*"([^"]*)"/i);
  if (mn && facts.nama_lengkap === undefined) facts.nama_lengkap = mn[2];
}
const merged = {}, changed = {};
for (const f of FACT_FIELDS) {
  const max  = PANJANG[f] || 120;
  const baru = KOSONG(facts[f]) ? '' : BERSIH(facts[f], max);
  const lama = BERSIH(prev[f], max);
  merged[f]  = baru || lama;
  changed[f] = merged[f] !== '' && merged[f] !== lama;
}

// ── Detektor pertanyaan galian (2026-09-14) ──
// SAMA PERSIS di Process All dan Rakit Konteks - UAT seksi R memeriksanya.
// Membaca teks yang benar-benar terkirim ke prospek, per kalimat tanya, dan
// mengembalikan kolom STATS yang ditanyakan. Nama orang ditanya dengan "siapa",
// nama usaha dengan "apa"; kalimat tanpa tanda tanya tidak pernah dihitung.
const slotDitanya = (teks) => {
  const hasil = new Set();
  const kalimat = String(teks || '').toLowerCase().match(/[^.?!\n]+[.?!]*/g) || [];
  for (const k of kalimat) {
    if (!/\?/.test(k)) continue;
    const namaUsaha =
         /\bnama(nya)?\s+(usaha|bisnis|brand|toko|perusahaan|lembaga|kantor|olshop|merek|merk|klinik|sekolah|kursus|bimbel)\w*\b[^.?!\n]{0,20}\b(apa|siapa)\b/.test(k)
      || /\b(usaha|bisnis|brand|toko|perusahaan|lembaga|kantor|olshop|merek|merk|klinik|sekolah|kursus|bimbel)\w*\s+nama(nya)?\s+(apa|siapa)\b/.test(k);
    // Nama orang dinilai per kalimat DAN per klausa (2026-09-18): "nama kakak siapa, dan
    // nama usahanya apa?" menanyakan dua hal - "nama usaha" di klausa lain tidak boleh
    // menggugurkan pertanyaan nama orangnya.
    const namaMilikLain = (s) =>
         /\bnama(nya)?\s+(usaha|bisnis|brand|toko|perusahaan|lembaga|kantor|olshop|merek|merk|klinik|sekolah|kursus|bimbel|produk|pelanggan|customer|admin|murid|klien|pasien|tamu)/.test(s)
      || /\b(usaha|bisnis|brand|toko|perusahaan|lembaga|kantor|olshop|merek|merk|klinik|sekolah|kursus|bimbel|produk|pelanggan|customer|admin|murid|klien|pasien|tamu)\w*\s+nama(nya)?\b/.test(s);
    const tanyaNamaOrang = (s) => !namaMilikLain(s) && (
         /\bnama(nya|mu)?\b[^.?!\n]{0,25}\bsiapa\b/.test(s)
      || /\bsiapa\b[^.?!\n]{0,12}\bnama(nya|mu)?\b/.test(s)
      || /\b(panggil|manggil)(nya|an|annya)?\b[^.?!\n]{0,20}\b(siapa|apa)\b/.test(s)
      || /\b(boleh|mau|yuk|ayo)\b[^.?!\n]{0,10}\bkenalan\b/.test(s)
      || /\b(ngobrol|bicara|chat|chatan|ngomong)\s+(sama|dengan|dgn|ama)\s+siapa\b/.test(s)
      || /\bdengan\s+(kak|kakak|bapak|ibu|pak|bu|mas|mbak)\s+siapa\b/.test(s));
    if (namaUsaha) hasil.add('nama_bisnis');
    if (tanyaNamaOrang(k) || k.split(/[,;]|\s(?:dan|serta)\s/).some(tanyaNamaOrang)) hasil.add('nama_lengkap');
    if (!namaUsaha && (
         /\b(bidang|jenis|industri|sektor)\b[^.?!\n]{0,25}\b(apa|apaan)\b/.test(k)
      || /\b(jualan|jual|bergerak)\b[^.?!\n]{0,20}\b(apa|apaan)\b/.test(k)
      || /\b(usaha|bisnis)(nya|mu)?\s+((kakak|kak)\s+)?(apa|apaan)\b/.test(k))) hasil.add('industri');
    if (/\b(kendala|masalah|repot|ribet|kewalahan|pusing|tantangan|keluhan|capek|susah)(nya)?\b/.test(k)
        && !/\b(lain|lainnya|kelewat|akibat\w*)\b/.test(k)) hasil.add('masalah_utama');
    if (/\b(berapa|brp)\b/.test(k) && /\b(chat|pesan|dm|leads?|inquiry)/.test(k)
        && /\b(hari|sehari|harian|perhari|minggu|seminggu|bulan|sebulan)/.test(k)) hasil.add('volume_chat');
  }
  return hasil;
};

// ── PENANGKAP JAWABAN — MULAI ──
// IDENTIK di Process All dan Rakit Konteks (2026-09-23) - UAT seksi R memeriksanya.
// Process All memakainya untuk MENYIMPAN jawaban; Rakit Konteks memakainya supaya
// galian tidak menanyakan sesuatu yang sudah dijawab di pesan giliran ini.
// ── JAWABAN ATAS PERTANYAAN GALIAN (2026-09-14) ──
// Sheet live 2026-09-14: kolom fakta STATS kosong di SEMUA percakapan, termasuk
// percakapan 15 giliran yang sudah sampai tawaran deck - karena satu-satunya jalan
// masuk fakta adalah tag [FACTS], dan model tidak menulisnya. Ini jaring
// deterministiknya: kalau balasan TERAKHIR yang terkirim menanyakan tepat satu
// kolom, dan model tidak menulis [FACTS] untuk kolom itu, jawaban prospek disimpan
// langsung. Hanya mengisi kolom yang masih kosong - tidak pernah menimpa.
// Pesan mentah dipakai (bukan BERSIH) karena BERSIH menghapus baris baru tanpa
// menyisakan spasi, dan buffer debounce memisahkan pesan dengan baris baru.
const LEPAS_AWAL = /^\W*(?:(?:boleh|oke+|ok|iya+|ya+|sip|siap|mau|halo|hallo|hai|hi|oh|ah|eh|wah|wow|yah|anu|hm+|ehm+|em+|hehe\w*|wkwk\w*|haha\w*)\b[\s,.!]*(?:(?:kak|ka|kakak)\b[\s,.!]*)?)+/i;
const BUKAN_JAWABAN = /^\W*(gak|ga|nggak|enggak|engga|tidak|belum|rahasia|nanti|ntar|skip|no|nope|kenapa|buat apa|untuk apa|maksud\w*|bentar|sebentar|males|malas|aman|lancar|gimana|bagaimana)\b/i;
const EKOR = /[\s,]+(kak|ka|kakak|ya|yaa|sih|kok|deh|aja|saja)\s*$/i;
// SEMUA kata ekor di ujung, bukan cuma satu (uji 2026-09-23 "Rehan": "persewaan aja sih" tersimpan
// sebagai industri "persewaan aja"). Hanya untuk bidang usaha & jumlah chat. Nama usaha tetap
// memakai EKOR: di sana "X aja sih" sengaja ditolak BUKAN_NAMA_USAHA (artinya: belum ada nama).
const EKOR_SEMUA = /(?:[\s,]+(?:kak|ka|kakak|ya|yaa|sih|kok|deh|aja|saja))+\s*$/i;
const ambilJawaban = (kolom, pesan, dariPerkenalan) => {
  const mentah = String(pesan || '').trim().replace(LEPAS_AWAL, '').trim();
  const p = BERSIH(mentah.replace(/\s+/g, ' '), 400);
  if (!p || BUKAN_JAWABAN.test(p)) return '';
  if (/\?\s*$/.test(p) && p.split(' ').length <= 8) return '';   // dia balik bertanya
  const baris1 = BERSIH(mentah.split('\n')[0].replace(/\s+/g, ' '), 200);
  if (kolom === 'nama_lengkap') {
    const s = baris1.split(/[,.!?;:]/)[0]
      .replace(/^(?:(?:nama\s*(?:ku|saya|aku|gue|gw)|namaku|aku|saya|gue|gw|ini|dengan|dgn|sama|ama|panggil(?:\s+(?:aja|saja))?|biasa\s+dipanggil|dipanggil|kenalin)\s+)+/i, '')
      .split(/\s+(?:dari|di|owner|pemilik|founder|kak|ka|kakak|mas|mbak|pak|bu|ya|yaa|aja|saja|kok|deh|hehe\w*|wkwk\w*)(?=\s|$)/i)[0]
      .replace(/[^\p{L}\s'.-]/gu, '').replace(/\s+/g, ' ').trim();
    const kata = s.split(' ').filter(Boolean);
    if (!kata.length || kata.length > 3 || s.length < 2 || s.length > 40) return '';
    if (/^(aku|saya|kak|kakak|mau|mo|tanya|harga|terima|makasih|thanks|thank|sama|ama|dengan|dgn|ini|itu|nama|lagi|lg|siapa|udah|sudah|bisa|oke|ok|iya|ya|bot|admin)$/i.test(kata[0])) return '';
    return kata.map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' ');
