    if (BUKAN_NAMA_USAHA.test(s) || NAMA_USAHA_MUSTAHIL.test(s) || VOLUME_SPONTAN.test(s)) return '';   // 2026-09-23
    // Dagangan ("sewa raket padel aja", "jualan kue") menjawab APA usahanya, bukan namanya
