  }
  // v3.13: nama usaha di blok brief yang cuma jenis usaha bukan nama (lihat JENIS_BUKAN_NAMA). Live
  // 2026-09-23: REQUESTS mencatat nama_bisnis "sewa raket padel" - tercetak di cover deck.
  if (JENIS_BUKAN_NAMA(deckRequest.nama_bisnis)) {
    if (!deckRequest.industri) deckRequest.industri = deckRequest.nama_bisnis;
    deckRequest.nama_bisnis = merged.nama_bisnis && !JENIS_BUKAN_NAMA(merged.nama_bisnis) ? merged.nama_bisnis : '';
  }
  // GATE TINGKAT 1 — sejak 2026-08-30 hanya menahan NOTIFIKASI, bukan penyimpanan.
  // Sebelumnya brief yang belum punya nama_bisnis/industri/masalah_utama dibuang UTUH,
  // ikut membuang field lain yang sudah disebut prospek (volume, budget, deadline, dst).
  // Sekarang: apa pun yang sudah tertangkap tetap ditulis ke REQUESTS; kolom `kelengkapan`
  // yang membedakan brief matang dari brief mentah. Yang masih dibuang hanya blok kosong total.
  deckMissing = ['nama_bisnis', 'industri', 'masalah_utama'].filter(f => !deckRequest[f]);
  deckRejected = deckMissing.length > 0;
  isDeckRequest = DECK_FIELDS.some(f => deckRequest[f]);
  if (deckRejected) {
    console.warn('DECK_REQUEST tingkat 1 belum lengkap — tetap disimpan, notifikasi ditahan: '
                 + deckMissing.join(', '));
  }
  if (!isDeckRequest) {
    console.warn('DECK_REQUEST kosong total, tidak ada satu pun field terisi — tidak disimpan.');
  }
}
// ── Isi blok [DECK_REQUEST] ikut mengisi STATS (2026-09-14) ──
// Sampai v3.6 arahnya cuma satu: fakta STATS -> blok brief. Model yang menulis blok
// lengkap tapi lupa [FACTS] meninggalkan kolom STATS kosong selamanya.
// Hanya mengisi kolom yang masih kosong.
const DARI_DECK = [['nama_lengkap', 'nama'], ['nama_bisnis', 'nama_bisnis'], ['industri', 'industri'],
                   ['masalah_utama', 'masalah_utama'], ['volume_chat', 'volume_chat_harian'],
                   ['minat_paket', 'minat_paket'], ['budget_range', 'budget_range']];
for (const [fk, dk] of DARI_DECK) {
  if (!merged[fk] && deckRequest[dk]) {
    merged[fk]  = BERSIH(deckRequest[dk], PANJANG[fk] || 120);
    changed[fk] = true;
  }
}

// ── Jaring niat deck (2026-09-04) ──
// [TALK_TO_ADMIN] dan [DECK_REQUEST] sama-sama berujung pada kalimat "Steven akan
// menghubungi kakak", dan modelnya pernah memilih tag dari kalimat yang sedang dia
// TULIS, bukan dari yang prospek MINTA. Akibatnya mahal: cabang TALK_TO_ADMIN menulis
// bot_mode=OFF, jadi prospek yang minta dibuatkan deck justru membuat VIRA berhenti
// membalas dia, dan briefnya tidak tercatat sama sekali (kejadian 2026-09-04 13:55).
// Gerbang ini deterministik supaya tidak bergantung pada kepatuhan model.
// Sumber teksnya actualUserMessage (seluruh buffer debounce), bukan original_message
// yang hanya berisi pesan TERAKHIR — "boleh tolong dibuatin ya" sering disusul pesan
// lain sebelum bot membalas.
const PESAN_USER = String((preprocess && preprocess.actualUserMessage) || originalMessage || '')
                     .toLowerCase().trim();
const NIAT_DECK   = /\b(deck|pitch|penawaran|proposal)\b|dibuat(in|kan)|dibikin(in|kan)?/;
// Diperluas 2026-09-05: versi lama tidak mengenali "boleh minta kontaknya",
// "ada CP?", "mau tanya langsung ke orangnya" - padahal ketiganya permintaan
// bicara yang sah, dan regex ini yang memutuskan bot boleh dimatikan atau tidak.
// v3.13 (uji live 2026-09-23 14:05): + bahasa chat yang langsung diarahkan ke Steven
// ("kpn bs ngmng sm steven?", "hubungi steven") - dulu tidak dikenali, bot tidak dimatikan.
const NIAT_BICARA = /telp|telepon|telfon|call|ditelpon|ditelepon|ketemu|meeting|zoom|gmeet|disambungkan|sambungin|hubungi (aku|saya|gue|gw)|nomor(nya)? steven|kontak(nya)? (steven|orangnya|langsung)|minta kontak|\bcp\b|ngobrol (langsung|sama|dgn|dengan)|bicara (langsung|sama|dgn|dengan)|(tanya|chat|ngomong) (langsung|sama|dgn|dengan) (steven|orangnya|manusia|orang aslinya)|\b(ngobrol|ngbrl|ngobrl|ngomong|ngmng|ngmg|omong|bicara|bcr|diskusi|telpon|telepon|telp|telfon|call|chat|hubungi|kontak)\w*\s+((langsung|lgsg|lgsung)\s+)?((sama|sm|ama|dgn|dg|dengan|ke)\s+)?stev/;

// Persetujuan pendek atas tawaran deck: "boleh", "mau", "oke", "ya".
// Kalimat seperti ini tidak memuat kata "deck" sama sekali, jadi NIAT_DECK tidak
// kena - padahal justru inilah kalimat yang paling sering dipakai prospek untuk
// menyetujui tawaran. Kejadian 2026-09-05 14:34: prospek menjawab "boleh",
// briefnya tersimpan, tapi Steven tidak pernah dinotifikasi.
// Sumbernya `last_bot_reply` - teks yang BENAR-BENAR dikirim giliran sebelumnya,
// bukan ingatan model, jadi gerbang ini deterministik.
const BALASAN_LALU  = String(prev.last_bot_reply || '').toLowerCase();
const TAWARAN_DECK  = /\b(deck|pitch|penawaran|proposal)\b/.test(BALASAN_LALU);
const SETUJU_PENDEK = PESAN_USER.length <= 40
  && /^\W*(boleh|mau|oke+|ok|ya+|iya+|yes|sip|siap|gas|silakan|silahkan|tolong|please|lanjut)\b/.test(PESAN_USER);
const mintaDeck = (NIAT_DECK.test(PESAN_USER) || (TAWARAN_DECK && SETUJU_PENDEK))
                  && !NIAT_BICARA.test(PESAN_USER);
if (TAWARAN_DECK && SETUJU_PENDEK) {
  console.log('Persetujuan pendek atas tawaran deck terdeteksi: "' + PESAN_USER + '"');
}

// URUTAN PENTING: rakit briefnya DULU, batalkan handover BELAKANGAN. Kalau dibalik,
// prospek yang minta deck sebelum ada satu pun fakta tersimpan kehilangan dua-duanya:
// handover batal, dan `IF Deck Request` tetap false sehingga cabang decknya tidak jalan.
// Hasilnya Steven tidak menerima notifikasi apa pun. Handover hanya boleh dibatalkan
// kalau ada yang menggantikannya.

// Kalau prospek jelas minta deck tapi model lupa menulis bloknya, brief tetap dirakit
// dari fakta yang SUDAH tersimpan. Tidak ada yang dikarang di sini — hanya nilai yang
// pernah dikonfirmasi lewat [FACTS] atau baris STATS sebelumnya. Kalau belum ada fakta
// sama sekali, tidak ada yang dicatat dan itu memang jawaban yang benar.
if (mintaDeck && !isDeckRequest) {
  if (!deckRequest.nama && merged.nama_lengkap) deckRequest.nama = merged.nama_lengkap;
  const DARI_FACTS_2 = [['nama_bisnis', 'nama_bisnis'], ['industri', 'industri'],
                        ['masalah_utama', 'masalah_utama'], ['minat_paket', 'minat_paket'],
                        ['budget_range', 'budget_range'], ['volume_chat_harian', 'volume_chat']];
  for (const [dk, fk] of DARI_FACTS_2) {
    if (!deckRequest[dk] && merged[fk]) deckRequest[dk] = merged[fk];
  }
  isDeckRequest = DECK_FIELDS.some(f => deckRequest[f]);
  deckMissing   = ['nama_bisnis', 'industri', 'masalah_utama'].filter(f => !deckRequest[f]);
  deckRejected  = deckMissing.length > 0;
  console.warn(isDeckRequest
    ? 'Blok DECK_REQUEST tidak ditulis model padahal prospek memintanya. Brief dirakit dari fakta tersimpan.'
    : 'Prospek minta deck tapi belum ada satu pun fakta tersimpan. Handover dipertahankan.');
}

// Handover dibatalkan HANYA kalau jalur deck benar-benar akan jalan menggantikannya.
if (isTalkToAdmin && mintaDeck && isDeckRequest) {
  console.warn('Niat deck terdeteksi pada pesan yang ditandai TALK_TO_ADMIN. '
             + 'Handover dibatalkan supaya bot tidak dimatikan: ' + PESAN_USER.slice(0, 120));
  isTalkToAdmin = false;
}

// -- Gerbang mematikan bot (2026-09-05) --
// [TALK_TO_ADMIN] punya dua akibat yang bobotnya jauh berbeda: (a) Steven
// dinotifikasi, dan (b) bot BERHENTI membalas orang itu sampai bot_mode
// dinyalakan manual di sheet. Untuk nomor iklan, (b) adalah lead yang hilang
// permanen kalau modelnya salah memilih tag - dan model memang pernah memilih
// tag dari kalimat yang sedang dia tulis, bukan dari yang prospek minta.
// Mulai sekarang: notifikasi tetap dikirim setiap kali tag keluar, tapi bot
// hanya dimatikan kalau PROSPEK yang memang memintanya di pesan ini.
// Gagal ke arah "bot tetap hidup" jauh lebih murah daripada sebaliknya.
// Dua sumber niat bicara digabung supaya perbedaan kecil antara regex di sini
// dan di Preprocess tidak pernah menghasilkan keputusan yang berbeda.
// ── Persetujuan pendek atas tawaran diskusi (2026-09-22) ──
// Cermin dari TAWARAN_DECK + SETUJU_PENDEK di atas, untuk jalur yang berbeda.
// Sesudah decknya dikirim, VIRA menawarkan ngobrol langsung dengan Steven dan
// prospek menjawab "boleh". Kalimat itu tidak memuat SATU PUN kata di NIAT_BICARA,
// jadi tanpa gerbang ini matikanBot tidak pernah true: Steven menerima notifikasi
// yang berbunyi "VIRA MASIH membalas orang ini", padahal VIRA barusan menjanjikan
// Steven akan menghubunginya — dan VIRA terus mengobrol seperti tidak terjadi apa-apa.
// Kelas bug yang sama persis dengan insiden tawaran deck 2026-09-05 14:34.
// Sumbernya BALASAN_LALU (last_bot_reply) — teks yang BENAR-BENAR terkirim giliran
// sebelumnya, bukan ingatan model, jadi gerbang ini deterministik.
// Kata kerja 'menghubungi' sengaja TIDAK masuk daftar: kalimat penutup deck berbunyi
// "Steven sendiri yang akan menyusun dan menghubunginya langsung", dan itu bukan
// tawaran diskusi. !mintaDeck adalah lapis keduanya.
// v3.13: + tawaran menyambungkan ("Mau aku sambungkan supaya dia langsung menghubungi kakak?",
// uji live 2026-09-23 14:06) - dulu jawaban "iya" atas kalimat itu tidak dianggap setuju.
const TAWARAN_DISKUSI = /\b(diskusi|ngobrol|bicara|ngomong|meeting|ketemu|jadwal\w*|telepon|telpon|call)\b[^.?!\n]{0,40}\b(steven|langsung|aslinya|orangnya)\b|\b(steven|langsung|orangnya)\b[^.?!\n]{0,40}\b(diskusi|ngobrol|bicara|ngomong|meeting|ketemu)\b|\b(di)?(sambung|nyambung)\w*\b[^.?!\n]{0,40}\b(steven|dia)\b|\bsteven\b[^.?!\n]{0,40}\b(di)?(sambung|nyambung)\w*/.test(BALASAN_LALU);
const SETUJU_DISKUSI = TAWARAN_DISKUSI && SETUJU_PENDEK && !mintaDeck;
if (SETUJU_DISKUSI) {
  console.log('Persetujuan pendek atas tawaran diskusi terdeteksi: "' + PESAN_USER + '"');
}
// Persetujuan sependek ini SAH sebagai permintaan bicara walaupun modelnya lupa
// menulis tagnya. Tanpa promosi ini Steven tidak menerima notifikasi apa pun —
// persis kegagalan yang dulu terjadi di jalur deck dan harus ditambal terpisah.
if (SETUJU_DISKUSI && !isTalkToAdmin) {
  console.warn('Tawaran diskusi disetujui tapi model tidak menulis [TALK_TO_ADMIN]. '
             + 'Handover dinyalakan dari gerbang deterministik: ' + PESAN_USER.slice(0, 120));
  isTalkToAdmin = true;
}

// ── Minta bicara dengan Steven dalam bahasa chat (2026-09-23, v3.13) ──
// Uji live Steven 14:00-14:06, sesudah VIRA bilang "Nanti Steven yang bantu bahas detailnya
// langsung": "kpn y bs ngmngnya?" lalu "kpn bs ngmng sm steven?". Yang kedua membuat model menulis
// [TALK_TO_ADMIN] (notif terkirim), tapi NIAT_BICARA tidak mengenali "ngmng"/"sm", jadi bot TIDAK
// dimatikan dan VIRA membalas "Mau aku sambungkan...?". Keputusan Steven 2026-09-23: permintaan yang
// jelas langsung disambungkan - bot OFF, notif, balasan mengonfirmasi. Dua pola, keduanya sempit:
//   - PERMINTAAN (mau/bisa/bs/kapan/tolong/... tepat di depannya) + kata kerja bicara (termasuk
//     singkatan) yang langsung diarahkan ke Steven: "kpn bs ngmng sm steven?", "mau hubungi steven";
//   - "kapan bisa ngobrol / ngomong / call / dihubungi" - HANYA kalau pesan ini atau balasan
//     terakhirku menyebut Steven.
// Kalau model lupa menulis tag, handover dinyalakan dari sini (sama dengan SETUJU_DISKUSI).
// Tidak pernah dinyalakan dari sini: pesan yang menolak ("ga usah ngobrol sama steven") dan
// pertanyaan identitas ("ini lagi chat sama steven?", "beneran steven atau bot?") - tanpa kata
// permintaan, atau memuat bot/AI/beneran. Yang itu tetap diputuskan model (bagian IDENTITAS).
const MINTA_STEVEN = /\b(mau|pengen|pgn|pingin|ingin|minta|bisa|bs|boleh|tolong|kapan|kpn|gimana|gmn|cara|butuh|perlu)\b[^.?!\n]{0,12}\b(ngobrol|ngbrl|ngobrl|ngomong|ngmng|ngmg|omong|bicara|bcr|diskusi|telpon|telepon|telp|telfon|call|chat|hubungi|kontak)\w*\s+((langsung|lgsg|lgsung)\s+)?((sama|sm|ama|dgn|dg|dengan|ke)\s+)?stev/;
const TANYA_KAPAN_BICARA = /\b(kapan|kpn)\b[^.?!\n]{0,20}\b(ngobrol|ngbrl|ngomong|ngmng|ngmg|omong|bicara|diskusi|call|telpon|telepon|telp|ketemu|meeting|zoom|dihubungi|hubungi)\w*/;
const NEGASI_BICARA = /\b(ga|gak|nggak|ngga|gk|tidak|tdk|jangan|belum|blm)\b[^.?!\n]{0,15}\b(ngobrol|ngbrl|ngomong|ngmng|ngmg|omong|bicara|diskusi|telpon|telepon|telp|call|chat|hubungi|kontak|ketemu)/;
const TANYA_IDENTITAS = /\b(beneran|bneran|bot|robot|ai)\b/;
const mintaSteven = !NEGASI_BICARA.test(PESAN_USER) && !TANYA_IDENTITAS.test(PESAN_USER)
  && (MINTA_STEVEN.test(PESAN_USER)
      || (TANYA_KAPAN_BICARA.test(PESAN_USER) && (/\bstev/.test(PESAN_USER) || /\bsteven\b/.test(BALASAN_LALU))));
if (mintaSteven && !mintaDeck && !isTalkToAdmin) {
  console.warn('Prospek minta bicara dengan Steven tapi model tidak menulis [TALK_TO_ADMIN]. '
             + 'Handover dinyalakan dari gerbang deterministik: ' + PESAN_USER.slice(0, 120));
  isTalkToAdmin = true;
}

const mintaBicara = (preprocess && preprocess.wantsHuman === true)
                  || NIAT_BICARA.test(PESAN_USER)
                  || SETUJU_DISKUSI
                  || mintaSteven;
const matikanBot = isTalkToAdmin && mintaBicara;
if (isTalkToAdmin && !matikanBot) {
  console.warn('TALK_TO_ADMIN tanpa permintaan bicara yang eksplisit di pesan user. '
             + 'Steven tetap dinotifikasi, bot DIBIARKAN HIDUP: ' + PESAN_USER.slice(0, 120));
}

const bahasaMerged = (KOSONG(deckRequest.bahasa_deck) ? '' : BERSIH(deckRequest.bahasa_deck, 20))
                     || deteksiBahasa(PESAN_USER) || BERSIH(prev.bahasa, 20);

// ── CLEAN OUTPUT (buang semua tag) ──
let cleanOutput = aiOutput
  .replace(/\[\s*DECK_REQUEST\s*\][\s\S]*?\[\s*\/\s*DECK_REQUEST\s*\]/gi, '')
  .replace(/\[\s*\/?\s*DECK_REQUEST\s*\][\s\S]*$/gi, '')   // blok tak tertutup (output terpotong)
  .replace(/\[\s*SEND_MEDIA\s*(?::[^\]]*)?\]/gi, '')
  .replace(/\[TALK_TO_ADMIN\]/gi, '')
  .replace(/\[UNKNOWN\]/gi, '')
  .replace(/\[\s*FACTS\b[^\]]*\]/gi, '');

const preInternalStrip = cleanOutput;
const internalKeywords = ['berdasarkan faq','berdasarkan data','menurut data','dari faq','dari sheet','data terverifikasi','faq relevan','data yang tersedia','saya cek data','saya cek faq','saya cek sheet','cek di sheet','cek di database'];
const keywordPattern = internalKeywords.join('|');
cleanOutput = cleanOutput.replace(new RegExp(`^\\s*([^.!?]*?(${keywordPattern})[^.!?]*[.!?]\\s*)`, 'i'), '');
cleanOutput = cleanOutput.replace(new RegExp(`^\\s*(${keywordPattern}).*?(\\n|\\.|$)`, 'i'), '');
cleanOutput = cleanOutput.replace(/^\s*(Berdasarkan|Menurut|Dari)\s+(data|faq|sheet|referensi)[^.!?]*[.!?]\s*/i, '');
if (!cleanOutput.trim() && preInternalStrip.trim()) cleanOutput = preInternalStrip;
cleanOutput = cleanOutput.trim();

// bersihkan markdown (URL di-mask dulu supaya tidak ikut terpotong)
const urlRegex = /https?:\/\/[^\s)]+/g;
const maskedUrls = [];
cleanOutput = cleanOutput.replace(urlRegex, (m) => { maskedUrls.push(m); return `\x00URL${maskedUrls.length - 1}\x00`; });
cleanOutput = cleanOutput
  .replace(/\*\*([^*]+)\*\*/g, '$1').replace(/\*([^*]+)\*/g, '$1').replace(/_([^_]+)_/g, '$1')
  .replace(/~~([^~]+)~~/g, '$1').replace(/`([^`]+)`/g, '$1').replace(/[\*_~`]/g, '');
cleanOutput = cleanOutput
  .replace(/(\d)\s*[—–]\s*(\d)/g, '$1-$2').replace(/\s*[—–]\s*/g, ', ').replace(/\s*;\s*/g, ', ')
  .replace(/\s{2,}/g, ' ').replace(/\s+([,.])/g, '$1').replace(/,\s*,/g, ',').trim();
cleanOutput = cleanOutput.replace(/\x00URL(\d+)\x00/g, (_, idx) => maskedUrls[parseInt(idx)]);
cleanOutput = cleanOutput.replace(/(^|\n)([a-z])/g, (m, p1, p2) => p1 + p2.toUpperCase());

if (!cleanOutput || cleanOutput.trim() === '') {
  cleanOutput = isUnknown
    ? 'Maaf yaa, untuk yang ini aku belum tahu. Nanti aku cek dulu dan kabari lagi.'
    : 'Maaf, ada kendala sebentar. Boleh diketik ulang yaa.';
}

// -- DIHAPUS 2026-09-05: override balasan saat brief tingkat 1 belum lengkap --
// Blok lama mengganti kalimat AI dengan pertanyaan kaleng ('Boleh tahu nama
// bisnisnya dulu kak?'). Yang DIKIRIM ke prospek adalah pertanyaan itu, tapi yang
// DISIMPAN Simple Memory adalah tulisan asli AI. Giliran berikutnya prospek
// menjawab pertanyaan yang - menurut ingatan model - tidak pernah dia ajukan.
// Persis inilah yang terjadi 2026-09-05 14:35-14:45: prospek menjawab nama
// bisnisnya, VIRA menjawab 'aku belum paham maksudnya', lalu 'aku belum nanya
// apa-apa barusan'. Nama bisnisnya pun tidak pernah tersimpan, jadi override
// yang sama siap terpicu lagi di giliran berikutnya - lingkaran tertutup.
//
// Alasan blok ini dulu ada sudah hilang sejak patch 2026-08-30: brief tingkat 1
// yang belum lengkap TETAP ditulis ke REQUESTS, dan notifikasi ke Steven punya
// gerbangnya sendiri (`deck_layak` di Merge Brief). Jadi balasannya tidak lagi
// menjanjikan sesuatu yang tidak tercatat. Menggali nama bisnis dikembalikan ke
// tugas prompt (bagian MENGGALI, TINGKAT 1), tempat yang benar untuk itu.
if (deckRejected) {
  console.log('Brief tingkat 1 belum lengkap (' + deckMissing.join(', ')
            + '). Tetap disimpan; balasan AI TIDAK diubah.');
}

// ── RINGKAS (2026-09-23) ──
// Uji Steven 2026-09-23 ("abdul", parfum): 6 balasan 28-60 kata, hampir semuanya
// [merangkum jawaban prospek] + [promosi VIRA] + [pertanyaan], padahal prompt sudah melarang
// merangkum dan membatasi 2 kalimat. Prompt tetap tuas utamanya; ini jaring terakhir yang
// deterministik, HANYA untuk giliran galian biasa: prospek tidak sedang bertanya (jawaban
// atas pertanyaannya tidak boleh terpotong), bukan perkenalan, bukan brief/deck/diskusi,
// bukan handover, bukan [UNKNOWN], bukan media, tidak menyebut harga, dan balasannya
// memuat pertanyaan (yang disisakan pertanyaan terakhirnya).
//  1. Kalimat pernyataan yang menggemakan pesan prospek dibuang.
//  2. Lebih dari satu kalimat tanya -> sisakan satu: yang menanyakan galian_berikutnya, kalau
//     tidak ada, yang terakhir.
//  3. Masih > 2 kalimat atau > 30 kata -> pengakuan pendek (<= 4 kata) + kalimat tanya.
//  4. Ekor alasan di kalimat tanya dibuang: ", biar aku kebayang bebannya?" -> "?".
// Blok [DECK_REQUEST] sendiri tidak mengecualikan: model juga menulisnya sebagai pembaruan brief
// diam-diam (eval 2026-09-23). Balasan yang benar-benar menawarkan/mengabarkan deck sudah
// dikecualikan lewat LEWATI_RINGKAS (kata deck / Steven + teruskan) dan mintaDeck.
// Pesan perkenalan punya aturan sendiri di bawah: hanya pertanyaan nama + nama usaha yang tinggal.
// Setiap pemangkasan dicatat ke EVENTS lewat node Log EVENTS Ringkas.
const RINGKAS_MAKS_KALIMAT = 2, RINGKAS_MAKS_KATA = 30, PENGAKUAN_MAKS_KATA = 4;
// Sama dengan `pesanBertanya` di Rakit Konteks.
const PROSPEK_BERTANYA = /\?|\b(apa|apakah|gimana|gmn|bagaimana|berapa|brp|kenapa|knp|kapan|mana)\b/i.test(PESAN_USER);
const LEWATI_RINGKAS = /\brp\s?\d|\d\s?(rb|ribu|jt|juta)\b|\b(deck|pitch|proposal|basic|premium|landing page|link|brosur|katalog)\b|\bsteven\b[^.?!\n]{0,40}\b(teruskan|terusin|sambung\w*|hubung\w*|diskusi|ngobrol|bicara|langsung)\b|\b(teruskan|terusin|sambung\w*|hubungkan)\b[^.?!\n]{0,40}\bsteven\b/i;
const pecahKalimat = (t) => String(t || '').split(/(?<=[.?!])\s+|\n+/).map(s => s.trim()).filter(Boolean);
const hitungKata = (t) => String(t || '').split(/\s+/).filter(Boolean).length;
const NORMAL_KATA = { dlu: 'dulu', dl: 'dulu', trs: 'terus', trus: 'terus', sm: 'sama', yg: 'yang',
  gk: 'gak', ga: 'gak', nggak: 'gak', bs: 'bisa', org: 'orang', pesen: 'pesan', bales: 'balas',
