    if (unique.length === 1) {
      resolveRow(unique[0]);
    } else if (unique.length > 1) {
      // sistem yang bertanya: media TIDAK dikirim, Steven TIDAK dinotif
      isMediaAmbiguous = true;
      isSendMedia = false;
      isMediaManual = false;
      mediaUrl = ''; mediaCaption = '';
      mediaCandidates = unique.map(r => ({ key: String(r['Nama Link'] || '').trim() }));
      const opts = mediaCandidates.map(c => c.key).filter(Boolean);
      const optText = opts.length === 2 ? `${opts[0]} atau ${opts[1]}`
                    : `${opts.slice(0, -1).join(', ')}, atau ${opts[opts.length - 1]}`;
      cleanOutput = `Ada beberapa yang cocok kak, mau yang mana yaa, ${optText}?`;
      replyOverridden = true;
      console.log('SEND_MEDIA ambigu, tanya balik:', JSON.stringify(mediaCandidates));
    } else {
      console.warn('SEND_MEDIA key tidak ada di LINKS, fallback manual:', mediaKey);
      isSendMedia = false;
      isMediaManual = true;
      const userMsg = (preprocess && preprocess.actualUserMessage) || originalMessage || '';
      mediaRequestSummary = (mediaKey ? ('key="' + mediaKey + '" ') : '') + (userMsg ? ('| pesan user: ' + String(userMsg).slice(0, 300)) : '');
    }
  }
}

// ── MEDIA KE-2 (mis. foto + dokumen dalam satu balasan) ──
let isSendMedia2 = false, mediaUrl2 = '', mediaCaption2 = '';
if (isSendMedia && mediaUrl && !isMediaAmbiguous && mediaKeysAll.length >= 2) {
  let linkRows2 = [];
  try { linkRows2 = $('Rakit Konteks').first().json.katalog.links || []; } catch (e) {}
  const norm2 = s => String(s || '').toLowerCase().replace(/\s+/g, ' ').trim();
  const active2 = linkRows2.filter(r => /^\s*(aktif|active|on|ya)\s*$/i.test(String(r['Status'] || '')));
  const key2 = mediaKeysAll.find(k => k && k !== mediaKey) || '';
  const row2 = key2 ? active2.find(r => norm2(r['Nama Link']) === key2) : null;
  if (row2) {
    const tipe2 = norm2(row2['Tipe']);
    const url2 = rapikanUrl(row2['URL']);
    if (url2 && !url2.startsWith('<<') && url2 !== mediaUrl && tipe2 !== 'location' && tipe2 !== 'website') {
      isSendMedia2 = true;
      mediaUrl2 = url2;
      mediaCaption2 = String(row2['Caption'] || '').trim() || 'Ini file berikutnya yaa.';
    }
  }
}

// ── FAIL LOUD: file diminta tapi tidak ada di katalog ──
// Notifikasi ke Steven saja tidak cukup. Selama balasannya masih berbunyi seperti
// janji, prospek menunggu sesuatu yang tidak pernah dikirim.
if (isMediaManual) {
  const low = cleanOutput.toLowerCase();
  const menjanjikan = /\b(kirim|kirimin|share|bagikan|lampirkan)\b/.test(low)
                   || /\b(ini|berikut)\s+(video|foto|file|dokumen|brosur|deck)/.test(low);
  if (menjanjikan) {
    const alt = linkAktifNama.length
      ? ' Yang sudah siap sekarang: ' + linkAktifNama.join(', ') + '.'
      : '';
    cleanOutput = 'Maaf kak, file itu belum ada di katalogku jadi belum bisa aku kirim '
                + 'langsung. Sudah aku teruskan ke Steven yaa, biar dia yang kirim.' + alt;
    replyOverridden = true;
    console.warn('Balasan diganti: menjanjikan file yang tidak ada di LINKS. key=' + mediaKey);
  }
}

// ── NAMA TIDAK DIPAKAI MENYAPA (2026-09-15) ──
// Keputusan Steven: nama prospek hanya disimpan untuk catatan, tidak pernah dipakai
// di balasan - selalu "kak". Larangan di prompt saja terbukti tidak cukup (insiden
// 2026-09-15 14:11: "Halo Aldi, senang kenal sama kamu. Jadi Aldi mau tanya...").
// Jaring terakhir: nama yang tersimpan dihapus dari teks sebelum dikirim.
// Tidak disentuh: nama yang juga bagian nama usaha ("Andi" di "Andi Bakery"),
// nama di bawah 3 huruf, dan nama yang juga kata umum di balasan ("Indah", "Jaya").
const KATA_UMUM_NAMA = /^(indah|sari|bintang|cahaya|mulia|jaya|baik|berkah|tenang|damai|harapan|kasih|cinta|suci|murni|maju|sukses|abadi|bagus|pintar|cerdas|setia|aman|lancar|ramah|senang|bahagia|tulus|rajin|hebat|vira|steven)$/i;
const escRe = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const namaSimpan = String(merged.nama_lengkap || '').trim();
const bisnisSimpan = String(merged.nama_bisnis || '').toLowerCase();
// Nama yang disebut di pesan ini tapi TIDAK tersimpan (uji 2026-09-17: perkenalan
// menanyakan bidang usaha + nama, model tidak menulis [FACTS], lalu "Salam kenal Nadia"
// terkirim). Belum pasti nama, jadi hanya dihapus sesudah sapaan/panggilan.
const namaTebakan = (!namaSimpan && slotDitanyaLalu.includes('nama_lengkap'))
  ? ambilJawaban('nama_lengkap', (preprocess && preprocess.actualUserMessage) || originalMessage) : '';
let namaDihapus = false;
for (const [nama, dimanaSaja] of [[namaSimpan, true], [namaTebakan, false]]) {
  if (!nama) continue;
  const potongan = [...new Set([nama, ...nama.split(/\s+/)])]
    .filter(n => n.length >= 3 && !KATA_UMUM_NAMA.test(n) && !bisnisSimpan.includes(n.toLowerCase()))
    .sort((a, b) => b.length - a.length);
  for (const n of potongan) {
    const pola = escRe(n);
    const sebelum = cleanOutput;
    cleanOutput = cleanOutput
      .replace(new RegExp('\\b(kak|kakak|ka|mas|mbak|pak|bu|bapak|ibu|bang|sis|bro)\\s+' + pola + '\\b', 'gi'), '$1')
      .replace(new RegExp('\\b(halo|hai|hi|hallo|makasih|terima kasih|thanks|thank you|salam kenal|selamat datang|oke|siap|baik|nah|wah)(\\s*,?\\s+)' + pola + '\\b', 'gi'), '$1$2kak');
    if (dimanaSaja) cleanOutput = cleanOutput.replace(new RegExp('\\b' + pola + '\\b', 'gi'), 'kakak');
    if (cleanOutput !== sebelum) namaDihapus = true;
  }
}
if (namaDihapus) {
  cleanOutput = cleanOutput
    .replace(/\bkakak\s+kak\b/gi, 'kak').replace(/\bkak\s+kakak\b/gi, 'kak')
    .replace(/(^|\n)([a-z])/g, (m, p1, p2) => p1 + p2.toUpperCase());
  console.warn('Nama prospek dihapus dari balasan (aturan: selalu "kak").');
}

return [{
  json: {
    ...chatCounter, ...preprocess, ...item.json,
    cleanOutput,
    aiOutputRaw: aiOutput,
    isTalkToAdmin,
    isUnknown,
    needs_unknown: isUnknown ? 'true' : 'false',
    isSendMedia, mediaUrl, mediaCaption, mediaKey,
    isSendMedia2, mediaUrl2, mediaCaption2,
    isMediaManual, mediaRequestSummary,
    isMediaAmbiguous, mediaCandidates,
    isDeckRequest, deckRequest, deckRejected, deckMissing,
    // deckDiminta = prospek MEMINTA deck secara eksplisit di pesan ini, terlepas
    // dari lengkap-tidaknya brief. Dipakai Merge Brief supaya permintaan yang jelas
    // tetap dinotifikasi ke Steven walau tingkat 1 belum lengkap.
    deckDiminta: mintaDeck,
    // deckNotify = ada blok brief berisi, ATAU prospek meminta deck. Dipakai
    // Merge Brief (gerbang notifikasi) dan kolom STATS.deck_requested supaya
    // keduanya tidak pernah berbeda pendapat.
    deckNotify: isDeckRequest || mintaDeck,
    // matikanBot = satu-satunya nilai yang boleh menulis bot_mode = OFF.
    matikanBot,
    replyOverridden,
    // Teks yang benar-benar dikirim ke prospek; ditulis ke STATS.last_bot_reply.
    last_bot_reply: cleanOutput,
    // deckLayak = tingkat 1 lengkap. Ini yang menandai 'benar-benar minta deck'
    // (dipakai kolom STATS.deck_requested + gerbang notifikasi admin).
    deckLayak: isDeckRequest && !deckRejected,
    original_message: originalMessage,
    is_new_user: isNewUser,
    nama_lengkap_merged: merged.nama_lengkap,
    nama_changed:        changed.nama_lengkap,
    nama_lengkap_changed: changed.nama_lengkap,
    slotDitanyaLalu,
    slotTertangkap,
    namaDihapus,
    ringkas: ringkasAlasan,
    ringkas_asli: ringkasAlasan ? teksSebelumRingkas : '',
    needs_ringkas_log: ringkasAlasan ? 'true' : 'false',
    nama_bisnis_merged:  merged.nama_bisnis,
    nama_bisnis_changed: changed.nama_bisnis,
    industri_merged:     merged.industri,
    industri_changed:    changed.industri,
    masalah_utama_merged:  merged.masalah_utama,
    masalah_utama_changed: changed.masalah_utama,
    volume_chat_merged:  merged.volume_chat,
    volume_chat_changed: changed.volume_chat,
    budget_range_merged:  merged.budget_range,
    budget_changed:       changed.budget_range,
    budget_range_changed: changed.budget_range,
    minat_paket_merged:  merged.minat_paket,
    minat_paket_changed: changed.minat_paket,
    bahasa_merged: bahasaMerged,
  }
}];

// FORMAT MEDIA NOTIF — notifikasi manual ke Steven.
// Dua jalur masuk ke sini: (1) key tidak ada di katalog LINKS, (2) key ada
// tapi unduhannya gagal / bukan file. Keduanya dibedakan di baris 'Sebab'
// supaya jelas yang perlu dibetulkan isi sheet-nya atau link-nya.
const pa = $('Process All').first().json;
const cc = $('Chat Counter').first().json;
const key = $('Resolve User Row').first().json.resolved_key || cc.user_wa || '';
// 2026-09-14: nama yang dia sebutkan sendiri didahulukan; nama akun WA sering
// nama toko atau julukan, jadi hanya jadi keterangan.
const namaAsli = String(pa.nama_lengkap_merged || '').trim();
const namaWa = String(cc.user_name || '').trim();
const nama = namaAsli
  ? namaAsli + (namaWa && namaWa !== namaAsli ? ' (akun WA: ' + namaWa + ')' : '')
  : (namaWa ? namaWa + ' (nama akun WA)' : '');
const mediaKey = pa.mediaKey || '';
const summary = pa.mediaRequestSummary || '';
const urlKatalog = String(pa.mediaUrl || '').trim();
const sebab = urlKatalog
  ? ('file ADA di katalog tapi gagal diunduh -> ' + urlKatalog)
  : 'key tidak ada di katalog LINKS (atau statusnya belum Aktif)';

const message = `📸 [VIRA Steven] PERMINTAAN MEDIA - KIRIM MANUAL
User: ${key}
Nama: ${nama || '(belum ada nama)'}
Diminta: ${mediaKey || 'foto/video'}
Detail: ${summary || '(tidak ada detail)'}
Sebab: ${sebab}

User menunggu file dikirim. Balas langsung ke user yaa.
Chat: wa.me/${String(key).replace(/\D/g, '')}`;

const cfg = $('Parse Config').first().json.config;
let tujuan = [cfg.admin_phone].filter(Boolean);
if (!tujuan.length) { console.warn('admin_phone kosong — tidak ada tujuan notif media manual.'); return []; }

return tujuan.map(no => ({ json: { phone: String(no), message } }));

// COLLECT HANDOVER CONTEXT — STATS (fakta persisten) + MSG_BUFFER (transkrip sesi).
const digits = v => String(v ?? '').replace(/\D/g, '');
const key = $('Resolve User Row').first().json.resolved_key;

let statsRow = {};
try { statsRow = $('Read User STATS').all().map(i => i.json).find(r => digits(r['No WA']) === digits(key)) || {}; } catch (e) {}

let transcript = '';
try {
  const buf = $('Read MSG_BUFFER').all().map(i => i.json)
    .filter(r => digits(r['no_wa']) === digits(key))
    .sort((a, b) => Number(a.ts) - Number(b.ts));
  transcript = buf.map(r => `User: ${r.message}`).join('\n');
} catch (e) {}

const pa = $('Process All').first().json;
const profil = {
  // PRIORITAS: [FACTS] turn ini > nama_lengkap tersimpan > push name WA.
  // JANGAN pakai statsRow['Nama'] duluan — itu nama akun WhatsApp, bukan nama
  // yang user sebutkan sendiri.
  nama: pa.nama_lengkap_merged || statsRow['nama_lengkap'] || statsRow['Nama'] || $('Chat Counter').first().json.user_name || '',
  nama_akun_wa: statsRow['Nama'] || $('Chat Counter').first().json.user_name || '',
  no_wa: key,
  pesan_pertama: statsRow['Pesan Pertama'] || '',
  nama_bisnis: pa.nama_bisnis_merged || statsRow['nama_bisnis'] || '',
  industri: pa.industri_merged || statsRow['industri'] || '',
  masalah_utama: pa.masalah_utama_merged || statsRow['masalah_utama'] || '',
  volume_chat: pa.volume_chat_merged || statsRow['volume_chat'] || '',
  minat_paket: pa.minat_paket_merged || statsRow['minat_paket'] || '',
  budget_range: pa.budget_range_merged || statsRow['budget_range'] || '',
  brief_terisi: statsRow['brief_terisi'] || '(belum ada brief)',
  sudah_minta_deck: String(statsRow['deck_requested'] || '').trim().toUpperCase() === 'Y' ? 'ya' : 'belum',
  lead_source: $('Detect Lead Source').first().json.lead_source_final || statsRow['lead_source'] || '',
  jumlah_chat: statsRow['Counter'] || '',
};

return [{ json: {
  handover_profil: profil,
  handover_transcript: transcript || '(transkrip sesi tidak tersedia)',
  handover_trigger: 'DELEGATION'
}}];

parameters.text:
=Kamu asisten internal yang merangkum percakapan calon klien jasa AI Customer Service untuk Steven. Buat ringkasan SINGKAT, PADAT, FAKTUAL dalam Bahasa Indonesia. Hanya gunakan DATA PROFIL dan TRANSKRIP di bawah. JANGAN mengarang, tulis "belum diketahui" bila kosong. Tanpa basa-basi. Kalau "Nama akun WA" berbeda dari "Nama", pakai "Nama" dan sebutkan akun WA-nya dalam kurung. Kalau sama, sebut sekali saja.

ATURAN FORMAT (WAJIB): keluarkan PLAIN TEXT murni. DILARANG memakai markdown — tanpa tanda bintang (* atau **), tanpa underscore, tanpa backtick, tanpa heading (#), tanpa bullet simbol. Tulis label apa adanya, contoh: Profil Prospek: ...

Keluarkan PERSIS format berikut:
Profil Prospek: <nama, no WA, sumber>
Bisnisnya: <nama bisnis, industri, apa yang dijual>
