{{ $json.handover_transcript }}

parameters.jsCode:
// FORMAT HANDOVER MESSAGE — bungkus ringkasan LLM (atau fallback deterministik).

// Sanitizer: buang sisa markdown dari output LLM. Prompt sudah minta plain text,
// tapi LLM masih sering bocor bold (**...** / *...*) — WA tidak butuh formatting,
// dan bintang yang tertinggal bikin pesan tim lapangan terlihat kotor.
// Underscore sengaja TIDAK dihapus: berisiko kena nama kolom (unit_interest, dll).
const stripMd = s => String(s || '')
  .replace(/\*/g, '')             // ** dan *
  .replace(/`/g, '')              // backtick
  .replace(/^#{1,6}\s*/gm, '')    // heading markdown
  .replace(/[ \t]+$/gm, '')       // trailing space
  .replace(/\n{3,}/g, '\n\n')     // rapikan blank line beruntun
  .trim();

let summary = '';
try { const s = $('Summarize Handover').first().json; summary = (s.content && s.content[0] && s.content[0].text) || s.text || ''; } catch (e) {}
summary = stripMd(summary);

const ctx = $('Collect Handover Context').first().json;
const p = ctx.handover_profil || {};
const trigger = ctx.handover_trigger || 'DELEGATION';

if (!summary || !summary.trim()) {
  summary = `PROSPEK: ${p.nama || '-'}, ${p.no_wa || '-'}, sumber ${p.lead_source || 'belum diketahui'}
BISNIS: ${p.nama_bisnis || 'belum diketahui'}${p.industri ? ' (' + p.industri + ')' : ''}
MASALAH UTAMA: ${p.masalah_utama || 'belum dibahas'}
SKALA: ${p.volume_chat || 'belum diketahui'} chat/hari
MINAT: ${p.minat_paket || 'belum disebut'}, budget ${p.budget_range || 'belum dibahas'}
BRIEF DECK: ${p.sudah_minta_deck === 'ya' ? 'sudah — ' + p.brief_terisi : 'belum'}`;
}

const header = {
  DELEGATION: '🤝 [VIRA Steven] PROSPEK MINTA DISAMBUNGKAN',
  HITL: '🙋 [VIRA Steven] AMBIL ALIH CHAT',
  CALL: '📞 [VIRA Steven] MINTA DITELEPON',
}[trigger] || '📋 [VIRA Steven] HANDOVER';

// Sejak 2026-09-05 tag [TALK_TO_ADMIN] tidak selalu mematikan bot (lihat P1-6).
// Steven harus tahu mana yang sedang dia terima, kalau tidak dia menunggu giliran
// membalas untuk chat yang sebenarnya masih dipegang VIRA - atau sebaliknya.
const botMati = (() => { try { return $('Process All').first().json.matikanBot === true; } catch (e) { return true; } })();
const statusBot = botMati
  ? 'STATUS: VIRA sudah BERHENTI membalas orang ini. Balas manual, lalu set bot_mode=ON di STATS kalau mau diserahkan lagi ke VIRA.'
  : 'STATUS: VIRA MASIH membalas orang ini (prospek tidak minta disambungkan secara eksplisit). Set bot_mode=OFF di STATS kalau mau ambil alih.';

const message = `${header}

${summary}

${statusBot}

— Chat: wa.me/${p.no_wa}`;

const cfg = $('Parse Config').first().json.config;
let tujuan = [cfg.admin_phone];
tujuan = (tujuan || []).filter(Boolean);
if (!tujuan.length) { console.warn('Tidak ada nomor tujuan handover (admin_phone kosong).'); return []; }

return tujuan.map(no => ({ json: { phone: String(no), message } }));

// ============================================================
// Send WA + Verify (Kirimi)
// Gabungan node lama: "Reply Chat Kirimi" (HTTP Request) + "Check API Response" (Code).
//
// KENAPA DIGABUNG:
// n8n me-retry MULAI DARI node yang gagal (runData node sebelumnya dipertahankan).
// Kalau validasi berdiri sendiri sebagai node terpisah, klik Retry hanya mengulang
// validasi dengan respons Kirimi yang lama -> throw lagi -> WA tidak pernah
// terkirim ulang. Dengan digabung, satu klik Retry benar-benar mengirim ulang.
//
// On Error = Stop Workflow (sengaja, jangan diubah): supaya execution jadi merah,
// Error Notifier jalan, dan execution bisa di-retry dari mobile dashboard.
//
// Retry HTTP ditangani DI DALAM kode ini (3x, jeda 5 detik) supaya persis meniru
// perilaku lama node "Reply Chat Kirimi" (retryOnFail: true, waitBetweenTries: 5000).
// Retry TIDAK berlaku untuk kegagalan "HTTP 200 tapi status:false" -- sama seperti
// node "Check API Response" lama yang tidak punya retryOnFail. Ini disengaja:
// respons status:false berarti Kirimi sudah memproses permintaan, jadi mengirim
// ulang otomatis berisiko pesan dobel. Kirim ulang untuk kasus itu = keputusan
// manusia, lewat tombol Retry.
// ============================================================

const KIRIMI_URL = 'https://api.kirimi.id/v1/send-message';
const TIMEOUT_MS = 60000;
const MAX_HTTP_ATTEMPTS = 3;
const WAIT_MS = 5000;

const sleep = (ms) => new Promise((resolve) => {
  if (typeof setTimeout === 'function') { setTimeout(resolve, ms); } else { resolve(); }
});

// --- kredensial: dari sheet CONFIG, sama persis dengan node HTTP lama ---
const _cfgAll = $('Parse Config').first().json.config || {};
const cfg = {
  user_code: _cfgAll.kirimi_user_code,
  secret: _cfgAll.kirimi_secret,
  device_id: _cfgAll.kirimi_device_id,
};

const phone = $('Chat Counter').first().json.user_wa;
const message = $('Process All').first().json.cleanOutput;

if (!phone) {
  throw new Error('Kirimi: nomor tujuan kosong (Chat Counter.user_wa)');
}
if (message === undefined || message === null || String(message).trim() === '') {
  throw new Error('Kirimi: pesan kosong (Process All.cleanOutput)');
}
if (!cfg.user_code || !cfg.secret || !cfg.device_id) {
  throw new Error('Kirimi: kredensial tidak lengkap (user_code/secret/device_id)');
}

// ---- 1) KIRIM (dengan retry khusus kegagalan HTTP) ----
let responseData = null;
let lastErr = null;

for (let attempt = 1; attempt <= MAX_HTTP_ATTEMPTS; attempt++) {
  try {
    responseData = await this.helpers.httpRequest({
      method: 'POST',
      url: KIRIMI_URL,
      body: {
        user_code: cfg.user_code,
        secret: cfg.secret,
        device_id: cfg.device_id,
        phone: phone,
        message: message,
      },
      json: true,
      timeout: TIMEOUT_MS,
    });
    lastErr = null;
    break;
  } catch (e) {
    lastErr = e;
    console.log('Kirimi HTTP gagal (percobaan ' + attempt + '/' + MAX_HTTP_ATTEMPTS + '): ' + (e && e.message ? e.message : String(e)));
    if (attempt < MAX_HTTP_ATTEMPTS) { await sleep(WAIT_MS); }
  }
}

if (lastErr) {
  throw new Error('Kirimi HTTP gagal setelah ' + MAX_HTTP_ATTEMPTS + ' percobaan: ' + (lastErr && lastErr.message ? lastErr.message : String(lastErr)));
}

// ---- 2) VERIFIKASI ISI RESPONS (logika lama "Check API Response") ----
const rd = (responseData && typeof responseData === 'object') ? responseData : {};
const explicitFail = rd.success === false || rd.status === false;
const isSuccess = !explicitFail && (
  rd.status === true ||
  rd.success === true ||
  (rd.data && rd.data.id) ||
  (rd.message && rd.message !== 'error')
);

if (!isSuccess) {
  throw new Error('Kirimi API gagal (HTTP 200 tapi respons menolak): ' + JSON.stringify(responseData));
}

console.log('Kirimi sukses:', JSON.stringify(responseData));
return [{ json: rd }];

const chatCounter = $('Chat Counter').first().json;

// DATA LANGSUNG DARI CHAT COUNTER NODE
const userNumber = chatCounter.user_wa;
const userName = chatCounter.user_name;
const userMessage = chatCounter.stats_message || chatCounter.original_message;   // [V2] '[gambar]' kalau kiriman tanpa teks

// VALIDASI SEDERHANA
if (!userNumber) {
  throw new Error("user_wa tidak ditemukan di input!");
}

console.log("✅ Data berhasil di-extract:");
console.log("- No WA:", userNumber);
console.log("- Nama:", userName);
console.log("- Pesan:", userMessage);

return [{
  json: {
    search_no_wa: userNumber,
    user_name: userName,
    user_message: userMessage,
    timestamp: chatCounter.formatted_date + ' ' + chatCounter.formatted_time + ' WIB',
    source: "chat_counter_node",
    is_valid: userNumber !== "unknown"
  }
}];

// ====================================================================
// PROCESS COUNTER & MERGE DATA — VIRA Steven
// Baris STATS lama diambil dari Resolve User Row (userRow), bukan dari
// pembacaan ulang seluruh tab. Node 'Read STATS' dibuang: barisnya sudah
// dibawa sejak awal giliran, dan satu-satunya penulis STATS di antara
// keduanya (Update Buffer) tidak menyentuh Counter.
// Dipertahankan dari V4: No WA primer / lid backup, 'Tanggal Chat Pertama'
// dibaca dari kolom yang benar, error -> stop (bukan menulis baris "ERROR").
// ====================================================================
try {
    const chatCounter = $('Chat Counter').first().json;
    const resolve = $('Resolve User Row').first().json;
    const resolvedKey = resolve.resolved_key;

    if (!resolvedKey) {
        console.warn('resolved_key kosong - skip update STATS');
        return [];
    }

    const digits = v => String(v ?? '').replace(/\D/g, '');
    const userName = chatCounter.user_name || 'User';
    const userMessage = chatCounter.stats_message || chatCounter.original_message || '';
    const lid = digits(chatCounter.user_lid);

    const row = resolve.userRow || {};
    const existingRow = Object.keys(row).length ? row : null;
    console.log('Baris STATS: ' + (existingRow ? 'SUDAH ADA' : 'USER BARU'));

    let counter, pesanPertama, tanggalPertama, intensitasChat;
    if (existingRow) {
        counter = parseInt(existingRow.Counter || existingRow.counter || 0) + 1;
        intensitasChat = parseInt(existingRow['Intensitas Chat'] || existingRow.intensitas_chat || 0) + 1;
        const pesanLama = existingRow['Pesan Pertama'] || existingRow.pesan_pertama;
        pesanPertama = (pesanLama && String(pesanLama).trim() !== '') ? pesanLama : userMessage;
        const tglLama = existingRow['Tanggal Chat Pertama'];
        tanggalPertama = (tglLama && String(tglLama).trim() !== '') ? tglLama : null;
    } else {
        counter = 1;
        intensitasChat = 1;
        pesanPertama = userMessage;
        tanggalPertama = null;
    }

    const hariIni = () => new Date().toLocaleDateString('en-GB', {
        timeZone: 'Asia/Jakarta', day: '2-digit', month: '2-digit', year: 'numeric'
    });
    if (!tanggalPertama) tanggalPertama = hariIni();

    return [{ json: {
        'No WA': resolvedKey,
        'lid': lid,
        'Tanggal': tanggalPertama,
        'TanggalSekarang': hariIni(),
        'Nama': userName,
        'Pesan Pertama': pesanPertama,
        'Counter': counter,
        'Intensitas Chat': intensitasChat
    }}];

} catch (error) {
    // jangan menulis baris "ERROR" ke sheet - cukup log & stop.
    console.error('Process Counter ERROR: ' + error.message);
    return [];
}

// ====================================================================
// UPDATE GREETING FLAG (V4 - disederhanakan)
// Dulu: pattern-matching teks balasan (rapuh, tergantung susunan
// kalimat). Sekarang: cukup dari flag is_new_user — kalau eksekusi
// ini mengirim intro ke user baru (reply sudah SUKSES terkirim
// karena node ini jalan setelah Reply Chat Kirimi), tandai Y.
// ====================================================================
const isNewUser = $('Cek_user_status').first().json.is_new_user === true;

if (isNewUser) {
  console.log('📝 [GREETING] intro terkirim ke user baru -> greeting_sent = Y');
}

return [{
  json: {
    update_needed: isNewUser ? 'true' : 'false',
    greeting_sent: 'Y'
  }
}];

// NODE: Siapkan Vision Request   [BARU - V2 VISION]
// ====================================================================
// Rakit body DeepSeek (OpenAI-compatible) untuk membaca gambar user.
// Semua gambar dalam satu window debounce dikirim dalam SATU request
// (lebih murah + model bisa membandingkan antar gambar).
// Sumber gambar = URL -> DeepSeek yang fetch.
//   Kalau URL Kirimi ternyata TIDAK publik, ganti jadi data URI base64:
//   { type:'image_url', image_url:{ url:'data:image/jpeg;base64,<b64>' } }
//   dan tambahkan node Download (HTTP Request, responseFormat=file) sebelum ini.
// ====================================================================
const base = $('Cek_user_status').first().json;
const cfg = (() => { try { return $('Parse Config').first().json.config || {}; } catch (e) { return {}; } })();

const imgs = Array.isArray(base.vision_images) ? base.vision_images : [];
const maxImg = Math.max(1, Number(cfg.vision_max_images ?? 3) || 3);
const picked = imgs.slice(-maxImg).filter(im => im && im.url);

if (!picked.length) {
  // Harusnya tidak terjadi (IF Ada Gambar sudah menyaring), tapi jangan
  // sampai node ini mengirim request kosong ke DeepSeek.
  return [{ json: { vision_body: null, vision_image_count: 0, vision_skip: true } }];
}

const caption = String(base.user_message_final || '').trim();

const SYSTEM = [
  'Kamu asisten vision untuk Steven versi AI, chatbot WhatsApp yang menjual jasa AI Customer Service.',
  'Tugasmu HANYA mendeskripsikan gambar yang dikirim calon klien, supaya bot bisa membalas dengan tepat.',
  '',
  'ATURAN:',
  '- Bahasa Indonesia, padat, maksimal 5 kalimat per gambar.',
  '- Untuk tiap gambar tulis 2 baris:',
  '  KATEGORI: <pilih SATU> SCREENSHOT_CHAT | SCREENSHOT_SISTEM_ATAU_DASHBOARD | BROSUR_ATAU_IKLAN | LOGO_ATAU_BRANDING | FOTO_PRODUK_ATAU_TOKO | TANGKAPAN_LAYAR_PENAWARAN_ATAU_HARGA | KTP_ATAU_DOKUMEN_PRIBADI | BUKTI_TRANSFER | LAINNYA',
  '  ISI: apa yang terlihat.',
  '- Teks/angka penting di dalam gambar (nama bisnis, nominal, jumlah chat, tanggal, nama platform) tulis PERSIS apa adanya.',
  '- DILARANG menebak. Tidak terbaca -> tulis "tidak terbaca".',
  '- DILARANG menilai, menjawab pertanyaan user, atau memberi saran. Deskripsi saja.',
  '- PRIVASI: DILARANG menyalin NIK/nomor KTP, nomor rekening lengkap, NPWP, nomor kartu, atau data pelanggan pihak ketiga yang terlihat di screenshot. Sebut jenis dokumennya saja.',
  '- Lebih dari satu gambar -> beri nomor "Gambar 1", "Gambar 2", dst.'
].join('\n');

const content = picked.map(im => ({
  type: 'image_url',
  image_url: { url: String(im.url) }
}));

content.push({
  type: 'text',
  text: `Ada ${picked.length} gambar dari calon pembeli.` +
    (caption
      ? `\nPesan/caption yang user tulis: "${caption}"`
      : `\nUser tidak menulis pesan apa pun, hanya mengirim gambar.`) +
    `\nDeskripsikan sesuai format KATEGORI/ISI.`
});

const body = {
  model: String(cfg.vision_model || 'deepseek-v4-flash-vision-exp'),
  max_tokens: Math.max(200, Number(cfg.vision_max_tokens ?? 700) || 700),
  // OpenAI-compatible: SYSTEM jadi pesan pertama, bukan field top-level seperti Anthropic.
  messages: [
    { role: 'system', content: SYSTEM },
    { role: 'user', content }
  ]
  // Kalau completionTokens membengkak (thinking menyala), uncomment baris di bawah.
  // Jangan dipasang dari awal: kalau model exp menolak parameternya, hasilnya 400.
  // , thinking: { type: 'disabled' }
};

return [{ json: { vision_body: body, vision_image_count: picked.length, vision_skip: false } }];

// NODE: Rakit Konteks Gambar   [BARU - V2 VISION]
// ====================================================================
// Titik gabung dua cabang IF Ada Gambar:
//   - cabang TRUE  : input = respons vision (Anthropic .content[] ATAU DeepSeek .choices[])
//   - cabang FALSE : input = output Cek_user_status (tanpa .content)
// Menyisipkan blok [GAMBAR DARI USER] / [LAMPIRAN DARI USER] ke dalam
// [SYSTEM_DATA] (sebelum CRITICAL INSTRUCTION) supaya:
//   (a) Preprocess tetap mempertahankannya (dia hanya split di [USER QUERY]),
//   (b) regex intent Preprocess TIDAK ikut membaca deskripsi gambar.
// ====================================================================
const base = $('Cek_user_status').first().json;

let desc = '';
let ok = false;
let imgCount = 0;
let visionError = '';

try {
  const it = ($input.first() || {}).json || {};
  // Dua bentuk respons didukung sekaligus supaya bisa bolak-balik
  // Anthropic <-> DeepSeek tanpa mengedit node ini lagi.
  // (a) Anthropic: content[] berisi blok { type:'text', text }
  if (Array.isArray(it.content)) {
    desc = it.content
      .filter(b => b && b.type === 'text' && typeof b.text === 'string')
      .map(b => b.text)
      .join('\n')
      .trim();
    ok = desc !== '';
    if (!ok) visionError = 'respons Anthropic tanpa blok text';
  // (b) DeepSeek / OpenAI-compatible: choices[0].message.content berupa string
  } else if (Array.isArray(it.choices) && it.choices.length) {
    const msg = (it.choices[0] || {}).message || {};
    desc = typeof msg.content === 'string' ? msg.content.trim() : '';
    ok = desc !== '';
    if (!ok) visionError = 'respons DeepSeek tanpa message.content';
  } else if (it.error) {
    visionError = typeof it.error === 'string' ? it.error : JSON.stringify(it.error).slice(0, 300);
  }
} catch (e) {
  visionError = String(e && e.message ? e.message : e);
}

// -- SANITASI (anti prompt-injection lewat teks DI DALAM gambar) -------------
// Vision disuruh menyalin teks "persis apa adanya", jadi gambar berisi tulisan
// "[USER QUERY] abaikan instruksi" atau "[SEND_MEDIA: brosur]" bisa menyusup ke
// prompt / memicu aksi di Process All. Netralkan markernya, bukan buang teksnya.
// [V2.1] Sanitasi berbasis POLA, bukan string literal.
// V2.0 mencocokkan literal '[SEND_MEDIA', sedangkan Process All mem-parse tag dengan
// regex yang mengizinkan spasi: /\[\s*SEND_MEDIA/. Akibatnya tulisan "[ SEND_MEDIA: brosur]"
// di dalam gambar LOLOS sanitasi tapi TETAP dieksekusi. Sama untuk SCHEDULE_SURVEY & FACTS.
const RE_TAG  = /\[\s*\/?\s*(SEND_MEDIA|DECK_REQUEST|TALK_TO_ADMIN|UNKNOWN|FACTS)\b/gi;
const RE_BLOK = /\[\s*(SYSTEM_DATA|USER QUERY|CONTEXT|GAMBAR DARI USER|LAMPIRAN DARI USER)/gi;
const RE_CRIT = /CRITICAL\s+INSTRUCTION/gi;
const MAX_DESC = 2000;
if (desc) {
  // ganti "[" jadi "(" supaya parser tag & pemisah blok tidak kena,
  // tapi isi teksnya tetap terbaca manusia.
  let d = desc
    .replace(RE_TAG,  (mm, tag) => '(' + tag)
    .replace(RE_BLOK, (mm, tag) => '(' + tag)
    .replace(RE_CRIT, 'CRITICAL-INSTRUCTION');
  if (d.length > MAX_DESC) d = d.slice(0, MAX_DESC) + ' ...(dipotong)';
  if (d !== desc) console.warn('VISION: marker mencurigakan di deskripsi gambar - dinetralkan.');
  desc = d;
}

try { imgCount = Number($('Siapkan Vision Request').first().json.vision_image_count) || 0; } catch (e) { }
if (!imgCount) imgCount = Array.isArray(base.vision_images) ? base.vision_images.length : 0;

if (visionError) console.warn('VISION gagal:', visionError);

// [V2.1] blok mengikuti vision_mode. Di V2.0, mode mati tetap menghasilkan blok
// "sistem GAGAL membaca" -> terbaca klien sebagai fitur RUSAK, bukan fitur di luar paket.
const visionMode = (() => {
  try { return String($('Parse Config').first().json.config.vision_mode || 'full').toLowerCase(); }
  catch (e) { return 'full'; }
})();

let blok = '';
if (visionMode === 'off') {
  // perilaku V1.3: lampiran diabaikan sepenuhnya, tidak ada blok yang disisipkan.
  blok = '';
} else if (base.has_image && visionMode === 'full') {
  blok = ok
    ? `[GAMBAR DARI USER]\nUser baru saja mengirim ${imgCount} gambar. Hasil pembacaan gambar (sumber tepercaya, boleh kamu rujuk):\n${desc}\nTanggapi isi gambarnya. DILARANG bilang kamu tidak bisa melihat gambar.`
    : `[GAMBAR DARI USER]\nUser mengirim gambar tapi sistem GAGAL membacanya. Minta maaf singkat lalu minta user menuliskan inti isi gambarnya. DILARANG menebak isinya.`;
  if (Number(base.vision_images_dropped) > 0) {
    blok += `\nCatatan: user mengirim lebih banyak gambar, hanya ${imgCount} terakhir yang terbaca. Kalau relevan, minta user mengirim ulang yang belum terbahas.`;
  }
} else if (base.has_image || Number(base.other_media_count) > 0) {
  // mode 'ack' (gambar maupun bukan), ATAU media non-gambar di mode 'full'.
  const jenis = base.has_image
    ? (Number(base.other_media_count) > 0 ? 'gambar dan lampiran lain' : 'gambar')
    : 'lampiran non-gambar (video/pesan suara/dokumen/lokasi/stiker)';
  blok = `[LAMPIRAN DARI USER]\nUser mengirim ${jenis} yang BELUM bisa kamu buka. Akui dengan sopan dan ramah bahwa kirimannya sudah masuk, lalu minta intinya diketik singkat, atau tawarkan disambungkan ke tim. DILARANG menebak isinya. DILARANG bilang "sistem gagal membaca" atau menyalahkan sistem.`;
}

let ai = String(base.ai_input_text || '');
if (blok) {
  if (ai.includes('CRITICAL INSTRUCTION')) {
    ai = ai.replace('CRITICAL INSTRUCTION', blok + '\n\nCRITICAL INSTRUCTION');
  } else if (ai.includes('[USER QUERY]')) {
    ai = ai.replace('[USER QUERY]', blok + '\n\n[USER QUERY]');
  } else {
    ai = blok + '\n\n' + ai;
  }
}

return [{
  json: {
    ...base,
    ai_input_text: ai,
    image_desc: desc,
    vision_ok: ok,
    vision_error: visionError,
    vision_image_count: imgCount
  }
}];

// Rakit Konteks — VIRA Steven
// Membangun 5 blok data yang disisipkan ke system prompt.
// Aturan penting: kolom "Catatan Internal" (PROGRAM & LINKS) dan baris
// "Boleh Dibagikan = Tidak" (ABOUT_STEVEN) TIDAK BOLEH dikirim sebagai fakta.
const item = $input.first().json;
const cfg  = $('Parse Config').first().json.config || {};

// Baris sheet datang dari katalog cache (lihat node 'Muat Katalog'), bukan dari
// $('Read ...') langsung — saat cache HIT node Sheets-nya memang tidak dijalankan.
const KATALOG = item.katalog || { faq: [], program: [], links: [], about: [] };
const rows = (kunci) => (Array.isArray(KATALOG[kunci]) ? KATALOG[kunci] : []);
const txt = (v) => String(v ?? '').trim();
const aktif = (v) => /^(aktif|active|on|ya|yes)$/i.test(txt(v));

// ---------- 1. prospect_context ----------
let stats = {};
try { stats = $('Resolve User Row').first().json.userRow || $('Resolve User Row').first().json || {}; }
catch (e) { stats = {}; }

const TTL_HARI = parseInt(cfg.fact_ttl_days || '60', 10);
const sekarang = Math.floor(Date.now() / 1000);
const masihSegar = (ts) => {
  const t = parseInt(ts || '0', 10);
  if (!t) return true;                    // tidak ada stempel waktu -> anggap masih berlaku
  return (sekarang - t) < TTL_HARI * 86400;
};

const FAKTA = ['nama_lengkap', 'nama_bisnis', 'industri', 'masalah_utama',
               'volume_chat', 'budget_range', 'minat_paket'];
const barisProspek = [];
for (const f of FAKTA) {
  const nilai = txt(stats[f]);
  if (!nilai) continue;
  if (!masihSegar(stats[f + '_ts'])) continue;   // fakta basi dibuang, jangan dipakai menyapa
  barisProspek.push(`${f}: ${nilai}`);
}
if (txt(stats['Nama']))  barisProspek.push(`nama_wa: ${txt(stats['Nama'])}`);
if (txt(stats['bahasa'])) barisProspek.push(`bahasa_terakhir: ${txt(stats['bahasa'])}`);
if (txt(stats['deck_requested']) === 'Y') barisProspek.push('sudah_minta_pitch_deck: ya');

// ── Detektor pertanyaan galian (2026-09-14) ──
// SAMA PERSIS di Process All dan Rakit Konteks - UAT seksi R memeriksanya.
// Membaca teks yang benar-benar terkirim ke prospek, per kalimat tanya, dan
// mengembalikan kolom STATS yang ditanyakan. Nama orang ditanya dengan "siapa",
// nama usaha dengan "apa"; kalimat tanpa tanda tanya tidak pernah dihitung.
const slotDitanya = (teks) => {
  const hasil = new Set();
  const kalimat = String(teks || '').toLowerCase().match(/[^.?!\n]+[.?!]*/g) || [];
  for (const k of kalimat) {
    if (!/\?/.test(k)) continue;
    const namaUsaha =
         /\bnama(nya)?\s+(usaha|bisnis|brand|toko|perusahaan|lembaga|kantor|olshop|merek|merk|klinik|sekolah|kursus|bimbel)\w*\b[^.?!\n]{0,20}\b(apa|siapa)\b/.test(k)
      || /\b(usaha|bisnis|brand|toko|perusahaan|lembaga|kantor|olshop|merek|merk|klinik|sekolah|kursus|bimbel)\w*\s+nama(nya)?\s+(apa|siapa)\b/.test(k);
    // Nama orang dinilai per kalimat DAN per klausa (2026-09-18): "nama kakak siapa, dan
    // nama usahanya apa?" menanyakan dua hal - "nama usaha" di klausa lain tidak boleh
    // menggugurkan pertanyaan nama orangnya.
    const namaMilikLain = (s) =>
         /\bnama(nya)?\s+(usaha|bisnis|brand|toko|perusahaan|lembaga|kantor|olshop|merek|merk|klinik|sekolah|kursus|bimbel|produk|pelanggan|customer|admin|murid|klien|pasien|tamu)/.test(s)
      || /\b(usaha|bisnis|brand|toko|perusahaan|lembaga|kantor|olshop|merek|merk|klinik|sekolah|kursus|bimbel|produk|pelanggan|customer|admin|murid|klien|pasien|tamu)\w*\s+nama(nya)?\b/.test(s);
    const tanyaNamaOrang = (s) => !namaMilikLain(s) && (
         /\bnama(nya|mu)?\b[^.?!\n]{0,25}\bsiapa\b/.test(s)
      || /\bsiapa\b[^.?!\n]{0,12}\bnama(nya|mu)?\b/.test(s)
      || /\b(panggil|manggil)(nya|an|annya)?\b[^.?!\n]{0,20}\b(siapa|apa)\b/.test(s)
      || /\b(boleh|mau|yuk|ayo)\b[^.?!\n]{0,10}\bkenalan\b/.test(s)
      || /\b(ngobrol|bicara|chat|chatan|ngomong)\s+(sama|dengan|dgn|ama)\s+siapa\b/.test(s)
      || /\bdengan\s+(kak|kakak|bapak|ibu|pak|bu|mas|mbak)\s+siapa\b/.test(s));
    if (namaUsaha) hasil.add('nama_bisnis');
    if (tanyaNamaOrang(k) || k.split(/[,;]|\s(?:dan|serta)\s/).some(tanyaNamaOrang)) hasil.add('nama_lengkap');
    if (!namaUsaha && (
         /\b(bidang|jenis|industri|sektor)\b[^.?!\n]{0,25}\b(apa|apaan)\b/.test(k)
      || /\b(jualan|jual|bergerak)\b[^.?!\n]{0,20}\b(apa|apaan)\b/.test(k)
      || /\b(usaha|bisnis)(nya|mu)?\s+((kakak|kak)\s+)?(apa|apaan)\b/.test(k))) hasil.add('industri');
    if (/\b(kendala|masalah|repot|ribet|kewalahan|pusing|tantangan|keluhan|capek|susah)(nya)?\b/.test(k)
        && !/\b(lain|lainnya|kelewat|akibat\w*)\b/.test(k)) hasil.add('masalah_utama');
    if (/\b(berapa|brp)\b/.test(k) && /\b(chat|pesan|dm|leads?|inquiry)/.test(k)
        && /\b(hari|sehari|harian|perhari|minggu|seminggu|bulan|sebulan)/.test(k)) hasil.add('volume_chat');
  }
  return hasil;
};

// util - SAMA dengan Process All (dipakai penangkap jawaban di bawah)
const BERSIH = (s, max) => String(s ?? '')
  .split('').filter(ch => ch.charCodeAt(0) >= 32).join('')
  .replace(/\s+/g, ' ').trim().slice(0, max || 200);

// ── PENANGKAP JAWABAN — MULAI ──
// IDENTIK di Process All dan Rakit Konteks (2026-09-23) - UAT seksi R memeriksanya.
// Process All memakainya untuk MENYIMPAN jawaban; Rakit Konteks memakainya supaya
// galian tidak menanyakan sesuatu yang sudah dijawab di pesan giliran ini.
// ── JAWABAN ATAS PERTANYAAN GALIAN (2026-09-14) ──
// Sheet live 2026-09-14: kolom fakta STATS kosong di SEMUA percakapan, termasuk
// percakapan 15 giliran yang sudah sampai tawaran deck - karena satu-satunya jalan
// masuk fakta adalah tag [FACTS], dan model tidak menulisnya. Ini jaring
// deterministiknya: kalau balasan TERAKHIR yang terkirim menanyakan tepat satu
// kolom, dan model tidak menulis [FACTS] untuk kolom itu, jawaban prospek disimpan
// langsung. Hanya mengisi kolom yang masih kosong - tidak pernah menimpa.
// Pesan mentah dipakai (bukan BERSIH) karena BERSIH menghapus baris baru tanpa
// menyisakan spasi, dan buffer debounce memisahkan pesan dengan baris baru.
const LEPAS_AWAL = /^\W*(?:(?:boleh|oke+|ok|iya+|ya+|sip|siap|mau|halo|hallo|hai|hi|oh|ah|eh|wah|wow|yah|anu|hm+|ehm+|em+|hehe\w*|wkwk\w*|haha\w*)\b[\s,.!]*(?:(?:kak|ka|kakak)\b[\s,.!]*)?)+/i;
const BUKAN_JAWABAN = /^\W*(gak|ga|nggak|enggak|engga|tidak|belum|rahasia|nanti|ntar|skip|no|nope|kenapa|buat apa|untuk apa|maksud\w*|bentar|sebentar|males|malas|aman|lancar|gimana|bagaimana)\b/i;
const EKOR = /[\s,]+(kak|ka|kakak|ya|yaa|sih|kok|deh|aja|saja)\s*$/i;
// SEMUA kata ekor di ujung, bukan cuma satu (uji 2026-09-23 "Rehan": "persewaan aja sih" tersimpan
// sebagai industri "persewaan aja"). Hanya untuk bidang usaha & jumlah chat. Nama usaha tetap
// memakai EKOR: di sana "X aja sih" sengaja ditolak BUKAN_NAMA_USAHA (artinya: belum ada nama).
const EKOR_SEMUA = /(?:[\s,]+(?:kak|ka|kakak|ya|yaa|sih|kok|deh|aja|saja))+\s*$/i;
const ambilJawaban = (kolom, pesan, dariPerkenalan) => {
  const mentah = String(pesan || '').trim().replace(LEPAS_AWAL, '').trim();
  const p = BERSIH(mentah.replace(/\s+/g, ' '), 400);
  if (!p || BUKAN_JAWABAN.test(p)) return '';
